// ===================== CRM PERSISTENCE & STORAGE CONFIGURATION =====================
const LOCAL_STORAGE_KEY = 'crmLocalData';
if (typeof window !== 'undefined') {
    window.LOCAL_STORAGE_KEY = LOCAL_STORAGE_KEY;
}

// One-time fresh CRM reset to clear out previous demo enquiries, leads, tasks, and files
const FRESH_CRM_RESET_KEY = 'crm_fresh_clean_state_2026';
if (typeof window !== 'undefined' && typeof localStorage !== 'undefined') {
    try {
        if (localStorage.getItem(FRESH_CRM_RESET_KEY) !== 'true') {
            const current = localStorage.getItem(LOCAL_STORAGE_KEY);
            if (current) {
                try {
                    const parsed = JSON.parse(current);
                    if (parsed && typeof parsed === 'object') {
                        parsed.leads = [];
                        parsed.enquiries = [];
                        parsed.reminders = [];
                        parsed.tasks = [];
                        parsed.escalations = [];
                        parsed.dailyCaseUpdates = [];
                        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(parsed));
                    }
                } catch (e) {}
            } else {
                localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify({
                    leads: [],
                    enquiries: [],
                    reminders: [],
                    tasks: [],
                    escalations: [],
                    dailyCaseUpdates: []
                }));
            }
            if (window.indexedDB) {
                try {
                    const req = window.indexedDB.open('LoanitolCrmCacheDB_v2');
                    req.onsuccess = (e) => {
                        const db = e.target.result;
                        if (db && db.objectStoreNames.contains('leads')) {
                            const tx = db.transaction(['leads'], 'readwrite');
                            tx.objectStore('leads').clear();
                        }
                    };
                } catch (e) {}
            }
            localStorage.setItem(FRESH_CRM_RESET_KEY, 'true');
            console.log('🧹 Fresh CRM initialized: all previous demo leads, enquiries, tasks, and files cleared.');
        }
    } catch (e) {
        console.warn('Fresh reset notice:', e);
    }
}

// ===================== PASSWORD HASHING & CREDENTIAL SECURITY =====================
const PASSWORD_SALT = 'loanitol_crm_secure_salt_2026';

async function hashPassword(plainText, salt = PASSWORD_SALT) {
    if (!plainText) return '';
    try {
        if (typeof window !== 'undefined' && window.crypto && window.crypto.subtle) {
            const enc = new TextEncoder();
            const data = enc.encode(plainText + ':' + salt);
            const hashBuffer = await window.crypto.subtle.digest('SHA-256', data);
            const hashArray = Array.from(new Uint8Array(hashBuffer));
            return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
        }
    } catch (e) {
        console.warn('Subtle crypto error, falling back:', e);
    }
    let hash = 0;
    for (let i = 0; i < plainText.length; i++) {
        const char = plainText.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash |= 0;
    }
    return 'h_' + Math.abs(hash).toString(16);
}

