const LOCAL_USER_CREDENTIALS = window.LOCAL_USER_CREDENTIALS || [];

function getRoleDefaultDesignation(role) {
    switch (role) {
        case 'admin': return 'Administrator / MD';
        case 'msme_head': return 'Head of MSME Loans';
        case 'retail_secured_head': return 'Head of Retail Secured Loans (Retail Secured Dep Head)';
        case 'retail_unsecured_head': return 'Head of Retail Unsecured Loans (Retail Unsecured Dep Head)';
        case 'retail_head': return 'Head of Retail Loans';
        case 'ops_head': return 'Head of Operations & Credit';
        case 'cso': return 'Customer Service Officer (CSO)';
        case 'cse': return 'Customer Service Executive (CSE)';
        case 'credit_evaluator': return 'Credit Analyst / Underwriter';
        case 'legal': return 'Legal Officer / Legal Department Counsel';
        case 'legal_officer': return 'Legal Scrutiny Officer';
        case 'legal_head': return 'Head of Legal & Compliance';
        case 'bank_follow_officer': return 'Banking & Disbursal Officer';
        case 'accountant': return 'Accountant';
        default: return 'Loan Operations Executive';
    }
}

function normalizeUser(user) {
    if (!user) return null;
    const uid = String(user.userId || user.id || '').trim().replace(/^@/, '');
    if (!uid) return null;
    let role = user.role || 'cso';
    let department = user.department || 'msme';
    let designation = user.designation;

    if (uid === 'aneena_s') {
        role = (role === 'retail_head' || !role) ? 'retail_secured_head' : role;
        department = 'retail_secured';
        if (!designation || designation.includes('Retail Lending (Retail Head)') || designation.includes('Head of Retail Loans')) {
            designation = 'Head of Retail Secured Loans (Retail Secured Dep Head)';
        }
    } else if (uid === 'bilsy_j') {
        role = (role === 'retail_head' || !role) ? 'retail_unsecured_head' : role;
        department = 'retail_unsecured';
        if (!designation || designation.includes('Retail Lending & Operations') || designation.includes('Head of Retail Loans')) {
            designation = 'Head of Retail Unsecured Loans (Retail Unsecured Dep Head)';
        }
    } else if (uid === 'vyshnavi_r') {
        department = 'retail_unsecured';
        if (!designation || designation === 'Retail Loan Officer') {
            designation = 'Retail Loan Officer (Unsecured)';
        }
    } else if (department === 'software') {
        department = 'digital_marketing';
    } else if (uid === 'anjali_jp') {
        department = 'sme';
        if (!designation) designation = 'Head of SME Lending (SME Head)';
    } else if (uid === 'eldho_mathew' || String(user.displayName || '').toLowerCase().includes('eldho')) {
        department = 'legal';
        role = user.role || 'legal_officer';
        if (!designation) designation = 'Head Legal Counsel & Verification';
    }

    const defaultPerms = getDefaultPermissions(role);
    let perms = user.permissions ? { ...defaultPerms, ...user.permissions } : { ...defaultPerms };
    if (user.permissions && Array.isArray(user.permissions.pageAccess)) {
        // User has explicit module access defined by Admin - preserve exact list
        perms.pageAccess = [...user.permissions.pageAccess];
        if (typeof user.permissions.canManageDumpStore !== 'undefined') {
            perms.canManageDumpStore = !!user.permissions.canManageDumpStore;
        } else {
            perms.canManageDumpStore = perms.pageAccess.includes('dump-store');
        }
        if (typeof user.permissions.canManageDataCenter !== 'undefined') {
            perms.canManageDataCenter = !!user.permissions.canManageDataCenter;
        } else {
            perms.canManageDataCenter = perms.pageAccess.includes('data-center');
        }
    } else {
        perms.pageAccess = [...defaultPerms.pageAccess];
        if (perms.canManageDataCenter && !perms.pageAccess.includes('data-center')) {
            perms.pageAccess.push('data-center');
        }
        if (perms.canManageDumpStore && !perms.pageAccess.includes('dump-store')) {
            perms.pageAccess.push('dump-store');
        }
    }

    // Eldho Mathew default legal permissions (only if no custom permissions exist)
    if ((uid === 'eldho_mathew' || String(user.displayName || '').toLowerCase().includes('eldho')) && (!user.permissions || !Array.isArray(user.permissions.pageAccess))) {
        perms.canAccessAllSecuredAndMSME = true;
        perms.canAccessAllLegalLeads = true;
        if (!perms.pageAccess.includes('all-leads')) perms.pageAccess.push('all-leads');
        if (!perms.pageAccess.includes('enquiries')) perms.pageAccess.push('enquiries');
        if (!perms.pageAccess.includes('processing')) perms.pageAccess.push('processing');
        if (!perms.pageAccess.includes('pipeline')) perms.pageAccess.push('pipeline');
    }

    const isHashed = (user.passwordHash && user.passwordHash.length === 64) || (user.password && user.password.length === 64);
    const staffPass = getDisplayableUserPassword({ userId: uid, ...user });
    const plainPwd = user.plainPassword || (!isHashed && user.password ? user.password : staffPass);
    const pwdHash = user.passwordHash || (isHashed ? user.password : null);

    const isCoreStaff = uid === 'vyshnavi_r' || uid === 'admin_1' || uid === 'admin' || (typeof window.LOCAL_STAFF_MEMBERS !== 'undefined' && window.LOCAL_STAFF_MEMBERS.some(s => s.userId === uid));
    const activeStatus = isCoreStaff ? 'active' : ((user.status === 'deactivated' || user.status === 'inactive' || user.active === false) ? 'deactivated' : 'active');

    return {
        userId: uid,
        authUserId: user.authUserId || `AUTH_${uid}`,
        displayName: user.displayName || user.name || uid,
        email: user.email || `${uid.toLowerCase()}@loanitol.com`,
        phone: user.phone || '',
        password: plainPwd,
        plainPassword: plainPwd,
        passwordHash: pwdHash,
        role: role,
        designation: designation || getRoleDefaultDesignation(role),
        department: department,
        status: activeStatus,
        permissions: perms,
        createdAt: user.createdAt || '2026-01-15T09:00:00Z',
        lastLoginAt: user.lastLoginAt || null
    };
}
