function getMemberCountConfig(constitution) {
    if (!constitution) return null;
    const c = String(constitution).trim().toLowerCase();
    // For Proprietorship, single owner company so there are no partners or directors
    if (c === 'proprietorship' || c.includes('proprietor') || c.includes('single') || c.includes('individual')) {
        return null;
    }
    if (c.includes('llp')) {
        return {
            label: 'No. of Partners / Designated Partners',
            placeholder: 'e.g. 2',
            min: 2,
            key: 'partnersCount',
            icon: 'fas fa-user-friends'
        };
    }
    if (c === 'partnership' || c.includes('partner')) {
        return {
            label: 'No. of Partners',
            placeholder: 'e.g. 2',
            min: 2,
            key: 'partnersCount',
            icon: 'fas fa-user-friends'
        };
    }
    if (c.includes('private') || c.includes('pvt') || c.includes('limited') || c.includes('ltd')) {
        return {
            label: 'No. of Directors',
            placeholder: 'e.g. 2',
            min: 1,
            key: 'directorsCount',
            icon: 'fas fa-users-cog'
        };
    }
    if (c.includes('trust') || c.includes('society')) {
        return {
            label: 'No. of Trustees',
            placeholder: 'e.g. 3',
            min: 1,
            key: 'trusteesCount',
            icon: 'fas fa-hands-helping'
        };
    }
    return null;
}
window.getMemberCountConfig = getMemberCountConfig;

function getVerifiedBusinessConstitution(lead) {
    if (!lead || typeof lead !== 'object') return '';
    
    // Check if this lead belongs to the currently active viewing customer
    if (window.currentViewingLeadId && lead.id && String(lead.id) !== String(window.currentViewingLeadId)) {
        if (typeof leads !== 'undefined' && Array.isArray(leads)) {
            const activeLead = leads.find(x => String(x.id) === String(window.currentViewingLeadId));
            if (activeLead && activeLead.id === window.currentViewingLeadId) {
                lead = activeLead;
            }
        }
    }

    // 1. Explicit businessConstitution
    let candidate = (lead.businessConstitution || '').trim();

    // 2. If not set, check constitution field ONLY if it is not a retail customer type
    if (!candidate && lead.constitution) {
        const raw = String(lead.constitution).trim();
        const retailTypes = ['salaried', 'nri salaried', 'individual', 'salaried / professional'];
        if (!retailTypes.includes(raw.toLowerCase())) {
            candidate = raw;
        }
    }

    // 3. Check msmeCategory if still empty
    if (!candidate && lead.msmeCategory) {
        const cat = String(lead.msmeCategory).toLowerCase().trim();
        if (cat.includes('partnership')) candidate = 'Partnership Firm';
        else if (cat.includes('private') || cat.includes('pvt')) candidate = 'Private Limited (Pvt Ltd)';
        else if (cat.includes('llp')) candidate = 'Limited Liability Partnership (LLP)';
        else if (cat.includes('proprietor')) candidate = 'Proprietorship';
        else if (cat.includes('trust') || cat.includes('society')) candidate = 'Trust / Society';
    }

    if (!candidate) return '';

    // Standardize to recognized canonical form
    const cLower = candidate.toLowerCase();
    if (cLower.includes('proprietor')) return 'Proprietorship';
    if (cLower.includes('limited liability') || cLower === 'llp' || cLower.includes('llp')) return 'Limited Liability Partnership (LLP)';
    if (cLower.includes('private limited') || cLower.includes('pvt') || cLower === 'pvt ltd') return 'Private Limited (Pvt Ltd)';
    if (cLower.includes('public limited')) return 'Public Limited';
    if (cLower.includes('partnership')) return 'Partnership Firm';
    if (cLower.includes('trust') || cLower.includes('society')) return 'Trust / Society';

    return candidate;
}
window.getVerifiedBusinessConstitution = getVerifiedBusinessConstitution;

function getVerifiedLeadConstitution(lead) {
    if (!lead || typeof lead !== 'object') return '';
    const isRetail = (lead.category && lead.category.startsWith('Retail')) || lead.customerType === 'Salaried' || lead.customerType === 'NRI Salaried' || lead.customerType === 'Self-Employed Professional' || lead.customerType === 'Self-Employed Non-Professional';
    if (isRetail) {
        if (lead.customerType === 'Self Employed' || lead.constitution === 'Self Employed' || (lead.customerType && lead.customerType.includes('Self-Employed'))) {
            return getVerifiedBusinessConstitution(lead) || lead.customerType || 'Proprietorship';
        }
        return lead.customerType || (RETAIL_CUSTOMER_TYPES.includes(lead.constitution) ? lead.constitution : 'Individual');
    }
    return getVerifiedBusinessConstitution(lead) || lead.constitution || 'Proprietorship';
}
window.getVerifiedLeadConstitution = getVerifiedLeadConstitution;

function isMultiMemberEntity(lead) {
    if (!lead || typeof lead !== 'object') return false;
    const bizConst = (typeof getVerifiedBusinessConstitution === 'function') 
        ? getVerifiedBusinessConstitution(lead) 
        : (lead.businessConstitution || lead.constitution || '');
    const cLower = String(bizConst).trim().toLowerCase();
    // Proprietorship, Individual, Salaried are strictly single-owner / no partners
    if (cLower.includes('proprietor') || cLower.includes('single') || cLower.includes('individual') || cLower.includes('salaried')) {
        return false;
    }
    const cat = String(lead.checklistCategory || lead.category || '').toUpperCase();
    const subCat = (typeof getVerifiedLeadSubCategory === 'function') ? getVerifiedLeadSubCategory(lead, cat) : '';
    if (subCat === 'partnership' || subCat === 'llp' || subCat === 'pvt_ltd' || subCat === 'private_limited' || subCat === 'trust') {
        return true;
    }
    if (cLower.includes('partner') || cLower.includes('llp') || cLower.includes('private') || cLower.includes('pvt') || cLower.includes('trust') || cLower.includes('society')) {
        return true;
    }
    return false;
}
window.isMultiMemberEntity = isMultiMemberEntity;

function getVerifiedLeadSubCategory(lead, category) {
    if (!lead || typeof lead !== 'object') return 'proprietorship';
    const cat = (category || lead.checklistCategory || lead.category || 'MSME').toUpperCase();
    if (cat.includes('MSME') || cat.includes('BUSINESS')) {
        const msmeCat = (lead.msmeCategory || '').toLowerCase();
        if (msmeCat) return msmeCat;
        const bizConst = String(typeof getVerifiedBusinessConstitution === 'function' ? getVerifiedBusinessConstitution(lead) : (lead.businessConstitution || lead.constitution || '')).toLowerCase();
        if (bizConst.includes('partner')) return 'partnership';
        if (bizConst.includes('llp')) return 'llp';
        if (bizConst.includes('private') || bizConst.includes('pvt') || bizConst.includes('ltd')) return 'pvt_ltd';
        if (bizConst.includes('trust') || bizConst.includes('society')) return 'trust';
        return 'proprietorship';
    } else {
        // Retail Category
        const custType = String(lead.customerType || lead.constitution || '').toLowerCase();
        const retCat = (lead.retailCategory || '').toLowerCase();
        const loanTypeStr = String(lead.loanType || '').toLowerCase();

        if (retCat === 'salaried_pl') return 'salaried_pl';
        if (loanTypeStr.includes('personal') || /\bpl\b/i.test(loanTypeStr)) return 'salaried_pl';
        if (custType.includes('salaried')) return 'salaried_pl';
        if (custType.includes('nri')) return 'nri_salaried';
        if (custType.includes('doctor')) return 'doctor';
        
        const bizConst = String(lead.businessConstitution || (custType.includes('self') ? lead.constitution : '') || '').toLowerCase();
        if (bizConst.includes('partner') || retCat === 'partnership') {
            if (bizConst.includes('partner')) return 'partnership';
        }
        if (bizConst.includes('llp') || retCat === 'llp') return 'llp';
        if (bizConst.includes('private') || bizConst.includes('pvt') || retCat === 'pvt_ltd' || retCat === 'private_limited') return 'pvt_ltd';
        if (bizConst.includes('proprietor') || retCat === 'proprietorship') return 'proprietorship';
        if (retCat && retCat !== 'partnership') return retCat;
        return 'salaried_pl';
    }
}
window.getVerifiedLeadSubCategory = getVerifiedLeadSubCategory;

function getVerifiedMemberCount(lead) {
    if (!lead || !isMultiMemberEntity(lead)) return 0;
    const count = parseInt(lead.partnersCount || lead.noOfPartners || lead.directorsCount || lead.trusteesCount || 0);
    return count > 0 ? count : 2;
}
window.getVerifiedMemberCount = getVerifiedMemberCount;

function getVerifiedPartnerNames(lead) {
    if (!lead || !isMultiMemberEntity(lead)) return {};
    if (lead.partnerNames && typeof lead.partnerNames === 'object' && !Array.isArray(lead.partnerNames)) {
        const cleaned = {};
        const bizName = String(lead.firmName || lead.company || lead.businessName || lead.name || '').trim().toLowerCase();
        Object.keys(lead.partnerNames).forEach(k => {
            const val = String(lead.partnerNames[k] || '').trim();
            if (val && (!bizName || val.toLowerCase() !== bizName)) {
                cleaned[k] = val;
            }
        });
        return cleaned;
    }
    return {};
}
window.getVerifiedPartnerNames = getVerifiedPartnerNames;

