function formatLoanType(type) {
    if (!type || typeof type !== 'string') return '';
    const clean = type.trim();
    if (!clean) return '';
    if (clean.includes(',')) {
        return clean.split(',').map(part => formatLoanType(part)).filter(Boolean).join(', ');
    }
    
    const knownMap = {
        'project report': 'Project Report',
        'bridge loan': 'Bridge Loan',
        'distress funding': 'Distress Funding',
        'home loan': 'Home Loan',
        'personal loan': 'Personal Loan',
        'business loan': 'Business Loan',
        'car loan': 'Car Loan',
        'professional loan': 'Professional Loan',
        'lap': 'LAP',
        'msme loan': 'MSME Loan',
        'term loan': 'Term Loan',
        'machinery loan': 'Machinery Loan',
        'construction loan': 'Construction Loan',
        'project loan': 'Project Loan',
        'letter of credit': 'Letter of Credit',
        'packing credit': 'Packing Credit',
        'bank guarantee': 'Bank Guarantee',
        'commercial real estate loan': 'Commercial Real Estate Loan',
        'invoice discounting loan': 'Invoice Discounting Loan',
        'agri od': 'Agri OD',
        'working capital od / cc - cgtmse': 'Working Capital OD / CC - CGTMSE',
        'working capital od / cc - with collateral': 'Working Capital OD / CC - With Collateral'
    };
    
    const lower = clean.toLowerCase();
    if (knownMap[lower]) return knownMap[lower];
    
    return clean.split(/\s+/).map(word => {
        const wUpper = word.toUpperCase();
        if (['LAP', 'MSME', 'OD', 'CC', 'CGTMSE', 'NBFC', 'GST', 'ITR', 'CRE', 'LRD'].includes(wUpper)) return wUpper;
        if (word.length <= 2 && !['loan', 'od', 'cc'].includes(word.toLowerCase())) return word;
        return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
    }).join(' ');
}
window.formatLoanType = formatLoanType;

