function getBanksForCategory(cat) {
    if (!cat) return CATEGORY_BANKS['MSME'];
    const c = String(cat).trim();
    if (c === 'MSME') return CATEGORY_BANKS['MSME'];
    if (c === 'Other Segment' || c.toLowerCase().includes('other')) return CATEGORY_BANKS['Other Segment'];
    if (c === 'Retail - Unsecured' || c === 'Retail Unsecured' || c.toLowerCase().includes('unsecured')) return CATEGORY_BANKS['Retail - Unsecured'];
    if (c === 'Retail - Secured' || c === 'Retail Secured' || (c.toLowerCase().includes('secured') && !c.toLowerCase().includes('unsecured'))) return CATEGORY_BANKS['Retail - Secured'];
    if (c.toLowerCase().includes('retail')) return [...CATEGORY_BANKS['Retail - Unsecured'], ...CATEGORY_BANKS['Retail - Secured']];
    return CATEGORY_BANKS['MSME'];
}

function getLoanTypesForCategory(cat) {
    if (!cat || cat === 'all' || cat === 'All') return getAllAvailableLoanTypes();
    const c = String(cat).trim();
    let raw = [];
    if (c === 'MSME') raw = CATEGORY_LOAN_TYPES['MSME'];
    else if (c === 'Other Segment' || c.toLowerCase().includes('other')) raw = CATEGORY_LOAN_TYPES['Other Segment'];
    else if (c === 'Retail - Unsecured' || c === 'Retail Unsecured' || c.toLowerCase().includes('unsecured')) raw = CATEGORY_LOAN_TYPES['Retail - Unsecured'];
    else if (c === 'Retail - Secured' || c === 'Retail Secured' || (c.toLowerCase().includes('secured') && !c.toLowerCase().includes('unsecured'))) raw = CATEGORY_LOAN_TYPES['Retail - Secured'];
    else if (c.toLowerCase().includes('retail')) raw = [...(CATEGORY_LOAN_TYPES['Retail - Unsecured'] || []), ...(CATEGORY_LOAN_TYPES['Retail - Secured'] || [])];
    else raw = CATEGORY_LOAN_TYPES['MSME'] || [];

    const map = new Map();
    (raw || []).forEach(lt => {
        const fmt = formatLoanType(lt);
        if (fmt && !map.has(fmt.toLowerCase())) {
            map.set(fmt.toLowerCase(), fmt);
        }
    });
    return Array.from(map.values()).sort((a, b) => a.localeCompare(b));
}

function getCategoryForLoanType(loanType) {
    if (!loanType) return '';
    const ltUpper = String(loanType).trim().toUpperCase();
    const isMatch = (arr) => Array.isArray(arr) && arr.some(x => x.toUpperCase() === ltUpper);
    if (isMatch(CATEGORY_LOAN_TYPES['Other Segment']) || ltUpper.includes('PROJECT REPORT') || ltUpper.includes('BRIDGE') || ltUpper.includes('DISTRESS')) return 'Other Segment';
    if (isMatch(CATEGORY_LOAN_TYPES['MSME'])) return 'MSME';
    if (isMatch(CATEGORY_LOAN_TYPES['Retail - Unsecured'])) return 'Retail - Unsecured';
    if (isMatch(CATEGORY_LOAN_TYPES['Retail - Secured'])) return 'Retail - Secured';
    if (ltUpper.includes('HOME') || ltUpper.includes('LAP') || ltUpper.includes('MORTGAGE')) return 'Retail - Secured';
    if (ltUpper.includes('PERSONAL') || ltUpper.includes('CAR') || ltUpper.includes('PROFESSIONAL') || ltUpper.includes('BUSINESS')) return 'Retail - Unsecured';
    return '';
}

