window.syncEnquiryDynamicFields = function() {
    const category = document.getElementById('enqCategory')?.value || '';
    const constVal = document.getElementById('enqConstitution')?.value || '';
    const selectedProducts = (typeof window.getSelectedLoanProducts === 'function')
        ? (window.getSelectedLoanProducts('enqLoanTypeContainer', 'enqLoanType') || '')
        : (document.getElementById('enqLoanType')?.value || '');
    
    const prodLower = selectedProducts.toLowerCase();
    const isRetail = category && category.startsWith('Retail');
    const isMsme = category === 'MSME' || String(category || '').toUpperCase().includes('MSME');
    const isSalaried = (isRetail && (constVal === 'Salaried' || constVal === 'NRI Salaried')) || (!constVal && prodLower.includes('personal loan'));
    const isNriSalaried = isRetail && constVal === 'NRI Salaried';
    const isSelfEmployed = isRetail && (constVal === 'Self Employed' || constVal === 'Self-Employed Professional' || constVal === 'Self-Employed Non-Professional');
    const isBusiness = (!isRetail && category) || isSelfEmployed;

    // Show/hide Business Constitution / Customer Type wrap based on Category selection
    const constWrap = document.getElementById('enqConstitutionWrap');
    if (constWrap) {
        constWrap.style.display = category ? 'block' : 'none';
    }

    // Business Constitution dropdown: only show when Customer Type is Self Employed in Retail
    const bizWrap = document.getElementById('enqBizConstitutionWrap');
    const bizSelect = document.getElementById('enqBizConstitution');
    if (bizWrap) {
        bizWrap.style.display = isSelfEmployed ? 'block' : 'none';
        if (!isSelfEmployed && bizSelect) {
            bizSelect.value = '';
        }
    }

    // Determine active constitution for enquiry
    let activeConstitution = '';
    if (isMsme || (category && !isRetail)) {
        activeConstitution = constVal;
    } else if (isSelfEmployed) {
        activeConstitution = bizSelect?.value || '';
    }

    // Member count configuration based on user requirements:
    // Proprietorship -> No member count question (hidden)
    // Partnership -> No. of Partners
    // LLP -> No. of Partners / Designated Partners
    // Private Limited -> No. of Directors
    // Trust -> No. of Trustees
    const memberConfig = getMemberCountConfig(activeConstitution);
    const partnersWrap = document.getElementById('enqPartnersWrap');
    const partnersLabel = document.getElementById('enqPartnersLabel');
    const partnersInput = document.getElementById('enqPartnersCount');

    if (partnersWrap) {
        if (category && memberConfig) {
            partnersWrap.style.removeProperty('display');
            partnersWrap.style.display = 'block';
            if (partnersLabel) {
                partnersLabel.innerHTML = `<i class="${memberConfig.icon || 'fas fa-users'} text-gold mr-1"></i> ${memberConfig.label}`;
            }
            if (partnersInput) {
                partnersInput.placeholder = memberConfig.placeholder;
                partnersInput.min = memberConfig.min || 1;
            }
        } else {
            partnersWrap.style.setProperty('display', 'none', 'important');
            if (partnersInput) {
                partnersInput.value = '';
            }
        }
    }

    // Sync Existing Loan Details visibility based on selection
    const hasLoansSelect = document.getElementById('enqHasExistingLoans');
    const loanDetailsWrap = document.getElementById('enqExistingLoanDetailsWrap');
    if (hasLoansSelect && loanDetailsWrap) {
        loanDetailsWrap.style.display = hasLoansSelect.value === 'Yes' ? 'block' : 'none';
    }

    // Age field wrap: hide strictly for MSME category, keep for all other categories
    const ageWrap = document.getElementById('enqAgeWrap');
    const ageInput = document.getElementById('enqAge');
    if (ageWrap) {
        if (isMsme) {
            ageWrap.style.setProperty('display', 'none', 'important');
            if (ageInput) ageInput.value = '';
        } else {
            ageWrap.style.removeProperty('display');
            ageWrap.style.display = '';
        }
    }

    const isLap = prodLower.includes('lap') || prodLower.includes('loan against property') || (prodLower.includes('property') && !prodLower.includes('report'));
    const isCarLoan = prodLower.includes('car');
    const isProfLoan = prodLower.includes('professional');

    const isSecuredOrLap = (category === 'Retail - Secured') || isLap || prodLower.includes('home loan') || prodLower.includes('flat') || prodLower.includes('house') || prodLower.includes('land') || prodLower.includes('commercial purchase') || prodLower.includes('commercial construction') || prodLower.includes('mortgage');

    const propCatWrap = document.getElementById('enqPropertyCategoryWrap');
    if (propCatWrap) {
        propCatWrap.style.display = isSecuredOrLap ? 'block' : 'none';
        if (!isSecuredOrLap && document.getElementById('enqPropertyCategory')) {
            document.getElementById('enqPropertyCategory').value = '';
        }
    }

    const salSection = document.getElementById('enqSalariedSection');
    if (salSection) {
        salSection.style.display = isSalaried ? 'block' : 'none';
    }

    const nriSection = document.getElementById('enqNriSalariedSection');
    if (nriSection) {
        nriSection.style.display = isNriSalaried ? 'block' : 'none';
        if (isNriSalaried) {
            const hasLoansVal = document.getElementById('enqExistingLoans')?.value || '';
            window.onNriExistingLoansChange(hasLoansVal);
        }
    }

    const bizSection = document.getElementById('enqBusinessSection');
    if (bizSection) {
        bizSection.style.display = isBusiness ? 'block' : 'none';
    }

    const enqPropCat = document.getElementById('enqPropertyCategory')?.value || '';
    const propDetailsSec = document.getElementById('enqPropertyDetailsSection');
    if (propDetailsSec) {
        if (enqPropCat) {
            propDetailsSec.style.display = 'block';
            const title = document.getElementById('enqPropCatTitle');
            if (title) title.innerText = enqPropCat;
            const grid = document.getElementById('enqPropertyFieldsGrid');
            if (grid && (!grid.dataset.renderedCat || grid.dataset.renderedCat !== enqPropCat)) {
                grid.innerHTML = window.renderSecuredPropertyFieldsHtml('enq', enqPropCat, window.getSecuredPropertyData('enq'));
                grid.dataset.renderedCat = enqPropCat;
            }
        } else {
            propDetailsSec.style.display = 'none';
        }
    }

    const lapSection = document.getElementById('enqLapSection');
    if (lapSection) {
        lapSection.style.display = (isLap && !enqPropCat) ? 'block' : 'none';
        if (isLap && !enqPropCat) {
            const bldVal = document.getElementById('enqBuildingIncluded')?.value || '';
            window.onEnquiryBuildingIncludedChange(bldVal);
        }
    }

    const carSection = document.getElementById('enqCarLoanSection');
    if (carSection) {
        carSection.style.display = isCarLoan ? 'block' : 'none';
        if (isCarLoan) {
            const condVal = document.getElementById('enqCarCondition')?.value || '';
            window.onEnquiryCarConditionChange(condVal);
        }
    }

    const profSection = document.getElementById('enqProfLoanSection');
    if (profSection) {
        profSection.style.display = isProfLoan ? 'block' : 'none';
    }
};

window.onEnquiryCategoryChange = function(catVal, selectedLoanType) {
    window.renderLoanProductSelector('enqLoanTypeContainer', catVal, selectedLoanType);
    const ltSelect = document.getElementById('enqLoanType');
    if (ltSelect) {
        const types = getLoanTypesForCategory(catVal);
        ltSelect.innerHTML = `<option value="">-- Select Loan Product --</option>` + types.map(t => `<option value="${escapeHtml(t)}" ${selectedLoanType && t === selectedLoanType ? 'selected' : ''}>${escapeHtml(t)}</option>`).join('');
    }
    const constWrap = document.getElementById('enqConstitutionWrap');
    const constLabel = document.getElementById('enqConstitutionLabel');
    const constSelect = document.getElementById('enqConstitution');
    const ageWrap = document.getElementById('enqAgeWrap');
    const ageInput = document.getElementById('enqAge');
    const bizWrap = document.getElementById('enqBizConstitutionWrap');

    const isMsme = catVal === 'MSME' || String(catVal || '').toUpperCase().includes('MSME');
    const isRetail = catVal && catVal.startsWith('Retail');

    if (isMsme) {
        if (constWrap) constWrap.style.display = 'block';
        if (constLabel) {
            constLabel.innerHTML = `<i class="fas fa-building text-gold mr-1"></i> Business Constitution <span style="font-size:11px; font-weight:normal; color:var(--text2);">(Optional)</span>`;
        }
        if (constSelect) {
            const currentVal = constSelect.value;
            constSelect.innerHTML = `<option value="">-- Select Business Constitution (Optional) --</option>` + BUSINESS_CONSTITUTIONS.map(c => `<option value="${c}" ${currentVal === c ? 'selected' : ''}>${c}</option>`).join('');
            if (currentVal && BUSINESS_CONSTITUTIONS.includes(currentVal)) {
                constSelect.value = currentVal;
            } else {
                constSelect.value = '';
            }
        }
        // Age is removed strictly for MSME category only
        if (ageWrap) {
            ageWrap.style.setProperty('display', 'none', 'important');
        }
        if (ageInput) ageInput.value = '';
        if (bizWrap) bizWrap.style.display = 'none';
    } else if (isRetail) {
        if (constWrap) constWrap.style.display = 'block';
        if (constLabel) {
            constLabel.innerHTML = `<i class="fas fa-user-tag text-gold mr-1"></i> Customer Type <span style="font-size:11px; font-weight:normal; color:var(--text2);">(Optional)</span>`;
        }
        if (constSelect) {
            const currentVal = constSelect.value;
            constSelect.innerHTML = `<option value="">-- Select Customer Type (Optional) --</option>` + RETAIL_CUSTOMER_TYPES.map(c => `<option value="${c}" ${currentVal === c ? 'selected' : ''}>${c}</option>`).join('');
            if (currentVal && RETAIL_CUSTOMER_TYPES.includes(currentVal)) {
                constSelect.value = currentVal;
            } else if (currentVal === 'Self Employed') {
                constSelect.value = 'Self-Employed Professional';
            }
        }
        // Age is shown for Retail
        if (ageWrap) {
            ageWrap.style.removeProperty('display');
            ageWrap.style.display = '';
        }
        if (bizWrap) bizWrap.style.display = 'none';
    } else if (catVal === 'Other Segment') {
        if (constWrap) constWrap.style.display = 'block';
        if (constLabel) {
            constLabel.innerHTML = `<i class="fas fa-building text-gold mr-1"></i> Business Constitution <span style="font-size:11px; font-weight:normal; color:var(--text2);">(Optional)</span>`;
        }
        if (constSelect) {
            const currentVal = constSelect.value;
            constSelect.innerHTML = `<option value="">-- Select Business Constitution (Optional) --</option>` + BUSINESS_CONSTITUTIONS.map(c => `<option value="${c}" ${currentVal === c ? 'selected' : ''}>${c}</option>`).join('');
            if (currentVal && BUSINESS_CONSTITUTIONS.includes(currentVal)) {
                constSelect.value = currentVal;
            } else {
                constSelect.value = '';
            }
        }
        // Age is shown for all non-MSME categories
        if (ageWrap) {
            ageWrap.style.removeProperty('display');
            ageWrap.style.display = '';
        }
        if (bizWrap) bizWrap.style.display = 'none';
    } else {
        // No category selected (e.g. empty "-- Select Category (Optional) --")
        // Remove constitution, biz constitution, and partners fields from here
        if (constWrap) constWrap.style.display = 'none';
        if (constSelect) constSelect.value = '';
        if (bizWrap) bizWrap.style.display = 'none';
        if (ageWrap) {
            ageWrap.style.removeProperty('display');
            ageWrap.style.display = '';
        }
    }

    const vintageInput = document.getElementById('enqVintage');
    if (vintageInput) {
        vintageInput.disabled = false;
        vintageInput.placeholder = isRetail ? 'e.g. 5 Years' : 'e.g. 3 Years / 5 Years';
        vintageInput.style.opacity = '1';
        vintageInput.style.cursor = 'text';
    }
    window.syncEnquiryDynamicFields();
    window.syncEnquiryFieldLabels();
};

