window.syncSecuredLeadFlow = function(prefix) {
    const categoryEl = document.getElementById(prefix === 'addSec' ? 'addCategory' : 'editCategory');
    const category = categoryEl?.value || '';
    const sectionEl = document.getElementById(prefix === 'addSec' ? 'securedLoanDetailsSection' : 'editSecuredLoanDetailsSection');

    if (!sectionEl) return;

    if (category !== 'Retail - Secured') {
        sectionEl.style.display = 'none';
        return;
    }

    sectionEl.style.display = 'block';

    const custTypeEl = document.getElementById(prefix + 'CustomerType');
    const custType = custTypeEl?.value || '';

    const subTypeWrap = document.getElementById(prefix + 'CustomerSubTypeWrap');
    const loanProductSec = document.getElementById(prefix + 'LoanProductSection');
    const propCatSec = document.getElementById(prefix + 'PropertyCategorySection');
    const propDetailsSec = document.getElementById(prefix + 'PropertyDetailsSection');

    if (subTypeWrap) {
        subTypeWrap.style.display = custType ? 'block' : 'none';
    }

    if (loanProductSec) loanProductSec.style.display = 'block';
    if (propCatSec) propCatSec.style.display = 'block';

    const mainProd = document.getElementById(prefix + 'MainLoanProduct')?.value || 'Home Loan';
    const prodReqEl = document.getElementById(prefix + 'ProductRequirement');
    if (prodReqEl && prodReqEl.options.length <= 1) {
        window.populateSecuredProductRequirementOptions(prefix, mainProd, prodReqEl.value);
    }

    const propCat = document.getElementById(prefix + 'PropertyCategory')?.value || '';
    const badge = document.getElementById(prefix + 'PropertyCategoryBadge');

    if (badge) {
        if (propCat) {
            badge.innerHTML = `<i class="fas fa-check-circle mr-1"></i> ${escapeHtml(propCat)}`;
            badge.style.display = 'inline-block';
        } else {
            badge.style.display = 'none';
        }
    }

    if (propDetailsSec) {
        if (propCat) {
            propDetailsSec.style.display = 'block';
            const grid = document.getElementById(prefix + 'PropertyFieldsGrid');
            if (grid && (!grid.dataset.renderedCat || grid.dataset.renderedCat !== propCat)) {
                grid.innerHTML = window.renderSecuredPropertyFieldsHtml(prefix, propCat, window.getSecuredPropertyData(prefix));
                grid.dataset.renderedCat = propCat;
            }
        } else {
            propDetailsSec.style.display = 'none';
            const grid = document.getElementById(prefix + 'PropertyFieldsGrid');
            if (grid) {
                grid.dataset.renderedCat = '';
            }
        }
    }
};

window.populateSecuredProductRequirementOptions = function(prefix, mainProduct, selectedValue = '') {
    const prodReqEl = document.getElementById(prefix + 'ProductRequirement');
    if (!prodReqEl) return;

    const options = SECURED_LOAN_REQUIREMENTS[mainProduct] || SECURED_LOAN_REQUIREMENTS['Home Loan'] || [];
    prodReqEl.innerHTML = `<option value="">-- Select Requirement Option --</option>` +
        options.map(opt => `<option value="${escapeHtml(opt)}" ${opt === selectedValue ? 'selected' : ''}>${escapeHtml(opt)}</option>`).join('');
};

window.onSecuredCustomerTypeChange = function(prefix) {
    const custType = document.getElementById(prefix + 'CustomerType')?.value || '';
    const subTypeEl = document.getElementById(prefix + 'CustomerSubType');
    const labelEl = document.getElementById(prefix + 'CustomerSubTypeLabel');
    const wrapEl = document.getElementById(prefix + 'CustomerSubTypeWrap');

    if (wrapEl) {
        wrapEl.style.display = custType ? 'block' : 'none';
    }

    if (subTypeEl) {
        const subTypes = SECURED_CUSTOMER_TYPES[custType] || [];
        if (custType === 'Salaried') {
            if (labelEl) labelEl.innerText = 'Salaried Type (RI / NRI) *';
            subTypeEl.innerHTML = `<option value="">-- Select Salaried Type --</option>` +
                subTypes.map(st => `<option value="${st}">${st === 'RI' ? 'RI (Resident Indian)' : 'NRI (Non-Resident Indian)'}</option>`).join('');
        } else if (custType === 'NRI Salaried') {
            if (labelEl) labelEl.innerText = 'Salaried Type *';
            subTypeEl.innerHTML = `<option value="NRI" selected>NRI (Non-Resident Indian)</option>`;
        } else if (custType) {
            if (labelEl) labelEl.innerText = 'Business Constitution *';
            subTypeEl.innerHTML = `<option value="">-- Select Constitution --</option>` +
                subTypes.map(st => `<option value="${st}">${st}</option>`).join('');
        } else {
            subTypeEl.innerHTML = '<option value="">-- Select Option --</option>';
        }
    }

    const baseConstEl = document.getElementById(prefix === 'addSec' ? 'addConstitution' : 'editConstitution');
    if (baseConstEl && custType) {
        baseConstEl.value = custType;
    }

    window.syncSecuredLeadFlow(prefix);
};

window.onSecuredCustomerSubTypeChange = function(prefix) {
    const custType = document.getElementById(prefix + 'CustomerType')?.value || '';
    const subType = document.getElementById(prefix + 'CustomerSubType')?.value || '';
    const bizConstEl = document.getElementById(prefix === 'addSec' ? 'addBizConstitution' : 'editBizConstitution');

    if (bizConstEl && custType.startsWith('Self-Employed')) {
        if (subType === 'Proprietor' || subType === 'Proprietorship') bizConstEl.value = 'Proprietorship';
        else if (subType === 'Partnership') bizConstEl.value = 'Partnership';
        else if (subType === 'LLP') bizConstEl.value = 'LLP';
        else if (subType === 'Pvt. Ltd.' || subType === 'Private Limited') bizConstEl.value = 'Private Limited';
        else if (subType === 'Trust') bizConstEl.value = 'Trust';
    }

    if (prefix === 'addSec') {
        window.syncAddLeadDynamicFields();
    } else {
        window.syncEditLeadDynamicFields();
    }
    window.syncSecuredLeadFlow(prefix);
};

window.onSecuredMainProductChange = function(prefix) {
    const mainProduct = document.getElementById(prefix + 'MainLoanProduct')?.value || 'Home Loan';
    window.populateSecuredProductRequirementOptions(prefix, mainProduct);
    window.syncSecuredLeadFlow(prefix);
};

window.onSecuredProductRequirementChange = function(prefix) {
    const propCat = document.getElementById(prefix + 'PropertyCategory')?.value;
    const grid = document.getElementById(prefix + 'PropertyFieldsGrid');
    if (propCat === 'House' && grid) {
        grid.innerHTML = window.renderSecuredPropertyFieldsHtml(prefix, 'House', window.getSecuredPropertyData(prefix));
        grid.dataset.renderedCat = 'House';
    }
    window.syncSecuredLeadFlow(prefix);
};

window.onSecuredPropertyCategoryChange = function(prefix) {
    const propCat = document.getElementById(prefix + 'PropertyCategory')?.value || '';
    const grid = document.getElementById(prefix + 'PropertyFieldsGrid');
    if (grid && propCat) {
        grid.innerHTML = window.renderSecuredPropertyFieldsHtml(prefix, propCat, window.getSecuredPropertyData(prefix));
        grid.dataset.renderedCat = propCat;
    }
    window.syncSecuredLeadFlow(prefix);
};

window.initSecuredLeadSection = function(prefix, leadData = {}) {
    if (!leadData) return;
    const sec = leadData.securedLoanDetails || {};
    const propDetails = leadData.propertyDetails || sec.propertyDetails || {};
    const custType = sec.customerType || leadData.securedCustomerType || '';
    const subType = sec.customerSubType || leadData.securedCustomerSubType || '';
    const mainProd = sec.mainLoanProduct || (leadData.loanType && String(leadData.loanType).toUpperCase().includes('LAP') ? 'LAP' : 'Home Loan');
    const prodReq = sec.loanProductRequirement || leadData.securedProductRequirement || '';
    const propCat = leadData.propertyCategory || sec.propertyCategory || '';

    const custTypeEl = document.getElementById(prefix + 'CustomerType');
    if (custTypeEl && custType) {
        custTypeEl.value = custType;
        window.onSecuredCustomerTypeChange(prefix);
        const subTypeEl = document.getElementById(prefix + 'CustomerSubType');
        if (subTypeEl && subType) subTypeEl.value = subType;
    }

    const mainProdEl = document.getElementById(prefix + 'MainLoanProduct');
    if (mainProdEl && mainProd) {
        mainProdEl.value = mainProd;
        window.populateSecuredProductRequirementOptions(prefix, mainProd, prodReq);
        const prodReqEl = document.getElementById(prefix + 'ProductRequirement');
        if (prodReqEl && prodReq) prodReqEl.value = prodReq;
    }

    const propCatEl = document.getElementById(prefix + 'PropertyCategory');
    if (propCatEl && propCat) {
        propCatEl.value = propCat;
        const grid = document.getElementById(prefix + 'PropertyFieldsGrid');
        if (grid) {
            grid.innerHTML = window.renderSecuredPropertyFieldsHtml(prefix, propCat, propDetails);
            grid.dataset.renderedCat = propCat;
        }
    }

    window.syncSecuredLeadFlow(prefix);
};

window.extractSecuredLoanDetails = function(prefix) {
    const customerType = document.getElementById(prefix + 'CustomerType')?.value || '';
    const customerSubType = document.getElementById(prefix + 'CustomerSubType')?.value || '';
    const mainLoanProduct = document.getElementById(prefix + 'MainLoanProduct')?.value || '';
    const loanProductRequirement = document.getElementById(prefix + 'ProductRequirement')?.value || '';
    const propertyCategory = document.getElementById(prefix + 'PropertyCategory')?.value || '';
    const propertyDetails = window.getSecuredPropertyData(prefix);

    const securedLoanDetails = {
        customerType,
        customerSubType,
        mainLoanProduct,
        loanProductRequirement,
        propertyCategory,
        propertyDetails
    };

    return {
        securedLoanDetails,
        securedCustomerType: customerType,
        securedCustomerSubType: customerSubType,
        securedMainProduct: mainLoanProduct,
        securedProductRequirement: loanProductRequirement,
        propertyCategory,
        propertyDetails
    };
};

window.renderSecuredLeadViewCardHtml = function(l) {
    return '';
};

const FALLBACK_LEADS = [];
const FALLBACK_REMINDERS = [];
const FALLBACK_TASKS = [];
const FALLBACK_ESCALATIONS = [];
const FALLBACK_ENQUIRIES = [];
// LOCAL_STORAGE_KEY declared at top of app.js

function loadLocalState() {
    try {
        const stored = localStorage.getItem(LOCAL_STORAGE_KEY);
        if (!stored) {
            return {
                leads: [],
                enquiries: [],
                departments: (typeof window.SEED_BACKUP_DATA !== 'undefined' && window.SEED_BACKUP_DATA.departments) || [],
                users: (typeof window.SEED_BACKUP_DATA !== 'undefined' && window.SEED_BACKUP_DATA.users) || [],
                reminders: [],
                tasks: [],
                escalations: [],
                loanTypes: (typeof window.SEED_BACKUP_DATA !== 'undefined' && window.SEED_BACKUP_DATA.loan_types) || []
            };
        }
        const parsed = JSON.parse(stored);
        if (parsed && typeof parsed === 'object') {
            parsed.leads = Array.isArray(parsed.leads) ? parsed.leads : [];
            parsed.enquiries = Array.isArray(parsed.enquiries) ? parsed.enquiries : [];
            return parsed;
        }
        return null;
    } catch (error) {
        console.warn('Failed to load local state:', error);
        return null;
    }
}

window.saveLocalState = window.persistLocalState = function(leadOrId) {
    // 1. Debounce local storage persistence to prevent UI frame drops
    scheduleSaveLocalState(200);

    let targetLeadId = null;
    let targetEnqId = null;

    if (typeof leadOrId === 'string' && leadOrId.trim()) {
        const cleanId = leadOrId.trim();
        if (Array.isArray(leads) && leads.some(l => l && l.id === cleanId)) {
            targetLeadId = cleanId;
        } else if (Array.isArray(enquiries) && enquiries.some(e => e && e.id === cleanId)) {
            targetEnqId = cleanId;
        } else if (cleanId.startsWith('lead_')) {
            targetLeadId = cleanId;
        } else if (cleanId.startsWith('enq_') || cleanId.startsWith('sb_')) {
            targetEnqId = cleanId;
        }
    } else if (leadOrId && typeof leadOrId === 'object' && leadOrId.id) {
        const cleanId = String(leadOrId.id).trim();
        if (Array.isArray(leads) && leads.some(l => l && l.id === cleanId)) {
            targetLeadId = cleanId;
        } else if (Array.isArray(enquiries) && enquiries.some(e => e && e.id === cleanId)) {
            targetEnqId = cleanId;
        } else if (cleanId.startsWith('lead_')) {
            targetLeadId = cleanId;
        } else if (cleanId.startsWith('enq_') || cleanId.startsWith('sb_')) {
            targetEnqId = cleanId;
        }
    }

    // Targeted lead persistence: sync ONLY the changed record
    if (targetLeadId && leadsRef && Array.isArray(leads)) {
        const l = leads.find(x => x && x.id === targetLeadId);
        if (l) {
            if (typeof CrmIndexedDBCache !== 'undefined' && CrmIndexedDBCache.saveLead) {
                CrmIndexedDBCache.saveLead(l).catch(console.error);
            }
            leadsRef.child(targetLeadId).update(l).catch(console.error);
        }
    }

    // Targeted enquiry persistence: sync ONLY the changed record
    if (targetEnqId && enquiriesRef && Array.isArray(enquiries)) {
        const e = enquiries.find(x => x && x.id === targetEnqId);
        if (e) {
            enquiriesRef.child(targetEnqId).update(e).catch(console.error);
        }
    }
};

function applyLocalFallbackData() {
    const savedState = loadLocalState();
    const savedDepts = getLocalTableData('departments');
    departments = (Array.isArray(savedDepts) && savedDepts.length) ? savedDepts : [...DEFAULT_DEPARTMENTS];
    if (Array.isArray(departments)) {
        departments = departments.filter(d => d.id !== 'software');
        let dmDept = departments.find(d => d.id === 'digital_marketing');
        if (dmDept) {
            dmDept.name = 'Digital Marketing & Software';
            if (dmDept.code === 'MKTG') dmDept.code = 'MKTG-TECH';
        }
        let secDept = departments.find(d => d.id === 'retail_secured');
        if (secDept) {
            secDept.headId = 'aneena_s';
            secDept.name = 'Retail Secured';
        }
        let unsecDept = departments.find(d => d.id === 'retail_unsecured');
        if (unsecDept) {
            unsecDept.headId = 'bilsy_j';
            unsecDept.name = 'Retail Unsecured';
        }
    }
    
    const savedUsers = getLocalTableData('users');
    const sourceUsers = (Array.isArray(savedUsers) && savedUsers.length) ? savedUsers : (typeof LOCAL_USER_CREDENTIALS !== 'undefined' && LOCAL_USER_CREDENTIALS.length ? LOCAL_USER_CREDENTIALS : DEFAULT_INITIAL_USERS);
    const userMap = new Map();
    DEFAULT_INITIAL_USERS.forEach(u => {
        if (u && u.userId && !DUMMY_USER_IDS.has(u.userId)) userMap.set(u.userId, normalizeUser(u));
    });
    sourceUsers.forEach(u => {
        const uid = u && (u.userId || u.id);
        if (uid && !DUMMY_USER_IDS.has(uid)) userMap.set(uid, normalizeUser(u));
    });
    users = Array.from(userMap.values()).filter(u => u && !DUMMY_USER_IDS.has(u.userId));
    users.forEach(u => {
        if (u.userId === 'aneena_s') {
            u.role = 'retail_secured_head';
            u.department = 'retail_secured';
            u.designation = 'Head of Retail Secured Loans (Retail Secured Dep Head)';
        } else if (u.userId === 'bilsy_j') {
            u.role = 'retail_unsecured_head';
            u.department = 'retail_unsecured';
            u.designation = 'Head of Retail Unsecured Loans (Retail Unsecured Dep Head)';
        } else if (u.userId === 'vyshnavi_r') {
            u.department = 'retail_unsecured';
            u.designation = 'Retail Loan Officer (Unsecured)';
        } else if (u.department === 'software') {
            u.department = 'digital_marketing';
        }
    });
    if (savedState) {
        leads = (Array.isArray(savedState.leads) ? savedState.leads : []).filter(l => l && typeof l === 'object' && l.name && l.name !== 'undefined' && String(l.name).trim() !== '');
        enquiries = (Array.isArray(savedState.enquiries) ? savedState.enquiries : []).filter(e => !isDummyEnquiry(e));
        const rawTypes = Array.isArray(savedState.loanTypes) && savedState.loanTypes.length ? savedState.loanTypes : (typeof window.SEED_BACKUP_DATA !== 'undefined' && Array.isArray(window.SEED_BACKUP_DATA.loan_types) ? window.SEED_BACKUP_DATA.loan_types : [...FALLBACK_LOAN_TYPES]);
        const mapTypes = new Map();
        rawTypes.forEach(t => {
            const fmt = formatLoanType(t);
            if (fmt && !mapTypes.has(fmt.toLowerCase())) {
                mapTypes.set(fmt.toLowerCase(), fmt);
            }
        });
        loanTypes = Array.from(mapTypes.values());
        reminders = Array.isArray(savedState.reminders) ? savedState.reminders : [];
        tasks = Array.isArray(savedState.tasks) ? savedState.tasks : [];
        escalations = Array.isArray(savedState.escalations) ? savedState.escalations : [];
        window.dailyCaseUpdates = Array.isArray(savedState.dailyCaseUpdates) ? savedState.dailyCaseUpdates : [];
    } else {
        leads = [];
        enquiries = [];
        loanTypes = (typeof window.SEED_BACKUP_DATA !== 'undefined' && Array.isArray(window.SEED_BACKUP_DATA.loan_types)) ? [...window.SEED_BACKUP_DATA.loan_types] : [...FALLBACK_LOAN_TYPES];
        reminders = [];
        tasks = [];
        escalations = [];
    }

    // Sanitize loanType field on leads and enquiries
    leads.forEach(l => { if (l && l.loanType) l.loanType = formatLoanType(l.loanType); });
    enquiries.forEach(e => { if (e && e.loanType) e.loanType = formatLoanType(e.loanType); });
    if (typeof persistLocalState === 'function') {
        persistLocalState();
    }
}

// Immediately hydrate users and tables from local fallback data upon script evaluation
try {
    applyLocalFallbackData();
} catch (e) {
    console.warn('Early fallback hydration notice:', e);
}

async function checkFirebaseAccess() {
    return false;
}

// Status definitions
