            'processing': `<div class="panel"><div class="panel-header">Processing Leads</div><div class="panel-body"><div id="leadFilterBar"></div><div class="tbl-wrap"><table id="processingTable"><thead><tr><th>Customer & Dates</th><th>Category & Loan Product</th><th>Status</th><th>TAT / Duration</th><th>Action</th></tr></thead><tbody id="leads-table-body"></tbody></table></div></div></div>`,
