window.uploadLeadFolderDocument = async function(leadId, folderName, yearFolder, fileInput) {
    const files = getFilesFromUploadInput(fileInput);
    if (!files || !files.length) return;
    
    let l = (typeof leads !== 'undefined' && Array.isArray(leads)) ? leads.find(x => String(x.id) === String(leadId) || x.id === leadId) : null;
    if (!l && typeof tableMemoryCache !== 'undefined' && tableMemoryCache.leads) {
        l = tableMemoryCache.leads[leadId];
    }
    if (!l) {
        const fallbackId = window.currentViewingLeadId || window.currentLeadId || (typeof currentLeadId !== 'undefined' ? currentLeadId : null);
        if (fallbackId) {
            l = (typeof leads !== 'undefined' && Array.isArray(leads)) ? leads.find(x => String(x.id) === String(fallbackId) || x.id === fallbackId) : null;
            if (!l && typeof tableMemoryCache !== 'undefined' && tableMemoryCache.leads) {
                l = tableMemoryCache.leads[fallbackId];
            }
        }
    }
    if (!l) {
        toast('Lead record not found for document upload', 'error');
        return;
    }
    if (!Array.isArray(l.attachments)) l.attachments = [];
    
    // Normalize folderName to strip any HTML entities like &amp;
    const cleanFolder = String(folderName || 'General')
        .replace(/&amp;/g, '&')
        .replace(/&#39;/g, "'")
        .replace(/&quot;/g, '"')
        .trim();
        
    toast(`<i class="fas fa-spinner fa-spin" style="color:var(--gold); margin-right:6px;"></i>Processing ${files.length} document(s)...`, 'info');
    
    try {
        await addFilesToAttachmentArray(files, l.attachments, {
            folderName: cleanFolder,
            yearFolder: String(yearFolder || new Date().getFullYear()),
            autoRename: true,
            leadName: l.name
        });
    } catch (uploadErr) {
        console.error('Document reading error:', uploadErr);
        toast(`Upload failed: ${uploadErr.message || 'File reading error'}`, 'error');
        if (fileInput && fileInput.value !== undefined) fileInput.value = '';
        return;
    }
    
    // Clear input so selecting the same file again triggers onchange
    if (fileInput && fileInput.value !== undefined) fileInput.value = '';
    
    // Auto-sync uploaded documents with checkpoints and doc checklist
    const syncRes = (typeof window.syncLeadCheckpointsWithAttachments === 'function')
        ? window.syncLeadCheckpointsWithAttachments(l)
        : { newlyCompletedCount: 0 };
        
    await window.persistAndRefreshLeadDocuments(l.id, 'documents');
    
    if (syncRes.newlyCompletedCount > 0) {
        toast(`<i class="fas fa-check-double" style="color: #34d399; margin-right: 6px;"></i>Uploaded & auto-completed <b>${syncRes.newlyCompletedCount}</b> Checkpoint(s) for <b>${escapeHtml(cleanFolder)}</b>!`, 'success');
    } else {
        toast(`<i class="fas fa-file-upload" style="color: var(--gold); margin-right: 6px;"></i>Uploaded <b>${files.length}</b> document(s) into <b>${escapeHtml(cleanFolder)}</b>!`, 'success');
    }
};
var uploadLeadFolderDocument = window.uploadLeadFolderDocument;

