window.removeLeadAttachment = async function(leadId, idx) {
    let l = (typeof leads !== 'undefined' && Array.isArray(leads)) ? leads.find(x => String(x.id) === String(leadId) || x.id === leadId) : null;
    if (!l && typeof tableMemoryCache !== 'undefined' && tableMemoryCache.leads) {
        l = tableMemoryCache.leads[leadId];
    }
    if (!l || !Array.isArray(l.attachments) || idx < 0 || idx >= l.attachments.length) return;
    const removedDoc = l.attachments.splice(idx, 1)[0];
    
    // Re-synchronize checkpoints after removal
    if (l.checkpoints) {
        Object.keys(l.checkpoints).forEach(key => {
            if (l.checkpoints[key] && Array.isArray(l.checkpoints[key].documents)) {
                l.checkpoints[key].documents = l.checkpoints[key].documents.filter(d => d.name !== removedDoc.name && d.name !== removedDoc.originalName);
            }
        });
    }
    if (typeof window.syncLeadCheckpointsWithAttachments === 'function') {
        window.syncLeadCheckpointsWithAttachments(l);
    }
    await window.persistAndRefreshLeadDocuments(l.id, 'documents');
    toast(`<i class="fas fa-trash" style="color:#ef4444; margin-right:6px;"></i>Deleted <i>"${escapeHtml(removedDoc?.name || 'Document')}"</i>`, 'info');
};
var removeLeadAttachment = window.removeLeadAttachment;

window.downloadLeadAttachmentByDocName = function(leadId, docName) {
    let l = (typeof leads !== 'undefined' && Array.isArray(leads)) ? leads.find(x => String(x.id) === String(leadId) || x.id === leadId) : null;
    if (!l && typeof tableMemoryCache !== 'undefined' && tableMemoryCache.leads) {
        l = tableMemoryCache.leads[leadId];
    }
    if (!l) return;
    const a = (l.attachments || []).find(x => x.name === docName || x.originalName === docName);
    if (a?.dataUrl) {
        downloadDataUrlAttachment(a.dataUrl, a.name);
        return;
    }
    // Check checkpoints documents
    if (l.checkpoints) {
        for (const key of Object.keys(l.checkpoints)) {
            const doc = (l.checkpoints[key]?.documents || []).find(x => x.name === docName || x.originalName === docName);
            if (doc?.dataUrl) {
                downloadDataUrlAttachment(doc.dataUrl, doc.name);
                return;
            }
        }
    }
    toast('File download content not found', 'error');
};
var downloadLeadAttachmentByDocName = window.downloadLeadAttachmentByDocName;

