window.uploadDirectCheckpointDoc = async function(leadId, key, sectionId, idx, input) {
    const files = getFilesFromUploadInput(input);
    if (!files || !files.length) return;
    
    let l = (typeof leads !== 'undefined' && Array.isArray(leads)) ? leads.find(x => String(x.id) === String(leadId) || x.id === leadId) : null;
    if (!l && typeof tableMemoryCache !== 'undefined' && tableMemoryCache.leads) {
        l = tableMemoryCache.leads[leadId];
    }
    if (!l) {
        const fallbackId = window.currentViewingLeadId || window.currentLeadId || (typeof currentLeadId !== 'undefined' ? currentLeadId : null);
        if (fallbackId) {
            l = (typeof leads !== 'undefined' && Array.isArray(leads)) ? leads.find(x => String(x.id) === String(fallbackId) || x.id === fallbackId) : null;
            if (!l && typeof tableMemoryCache !== 'undefined' && tableMemoryCache.leads) {
                l = tableMemoryCache.leads[fallbackId];
            }
        }
    }
    if (!l) {
        toast('Lead not found for checkpoint document upload', 'error');
        return;
    }
    if (!Array.isArray(l.attachments)) l.attachments = [];
    if (!l.checkpoints) l.checkpoints = {};
    if (!l.checkpoints[key]) l.checkpoints[key] = { status: 'pending', remark: '', documents: [] };

    // Determine target folder based on section
    const isRetail = (l.checklistCategory || l.category) === 'Retail';
    let folderName = isRetail ? '1. KYC & Personal Identity' : '1. KYC & Business Registrations';
    if (sectionId === 'financials_yearly' || sectionId === 'income' || sectionId === 'income_firm' || sectionId === 'fin_years' || sectionId.startsWith('fin_')) {
        folderName = isRetail ? '2. Income & Salary Proof' : '2. Financial Statements & ITRs';
    } else if (sectionId === 'gst_yearly' || sectionId === 'gst_years' || sectionId.startsWith('gst_')) {
        folderName = isRetail ? '2. Income & Salary Proof' : '4. GST & Tax Returns';
    } else if (sectionId === 'partners' || sectionId.startsWith('partner')) {
        folderName = isRetail ? '1. KYC & Personal Identity' : '1. KYC & Business Registrations';
    } else if (sectionId === 'bank') {
        folderName = isRetail ? '3. Bank Account Statements' : '3. Bank & Working Capital Statements';
    } else if (sectionId === 'registrations' || sectionId === 'licence') {
        folderName = isRetail ? '5. Employment / Business Proof' : '1. KYC & Business Registrations';
    } else if (sectionId === 'loans' || sectionId === 'others' || sectionId === 'cibil') {
        folderName = isRetail ? '6. Existing Loan Track & CIBIL' : '6. Existing Loan Track & Sanction';
    } else if (sectionId === 'property') {
        folderName = isRetail ? '4. Property & Collateral Docs' : '5. Collateral & Property Legal';
    }

    let yearFolder = String(new Date().getFullYear());
    const sec = (typeof getCheckpointsConfig === 'function') ? getCheckpointsConfig(l.checklistCategory || l.category, l.msmeCategory || l.retailCategory || 'proprietorship', l) : [];
    const matchedSec = sec.find(s => s.id === sectionId);
    const cpText = matchedSec?.checkpoints?.[idx] || '';
    const yrMatch = cpText.match(/20\d{2}-\d{2}/);
    if (yrMatch) {
        yearFolder = `FY ${yrMatch[0]}`;
    }
    const partnerMatch = cpText.match(/(?:Partner|Director|Designated Partner|Trustee)\s+(\d+)/i);
    if (partnerMatch) {
        yearFolder = partnerMatch[0];
    }

    toast(`<i class="fas fa-spinner fa-spin" style="color:var(--gold); margin-right:6px;"></i>Processing checkpoint document(s)...`, 'info');

    try {
        await addFilesToAttachmentArray(files, l.attachments, {
            folderName,
            yearFolder,
            autoRename: true,
            leadName: l.name
        });
    } catch (uploadErr) {
        console.error('Checkpoint file reading error:', uploadErr);
        toast(`Upload failed: ${uploadErr.message || 'File reading error'}`, 'error');
        if (input && input.value !== undefined) input.value = '';
        return;
    }

    if (input && input.value !== undefined) input.value = '';

    if (typeof window.syncLeadCheckpointsWithAttachments === 'function') {
        window.syncLeadCheckpointsWithAttachments(l);
    }
    l.checkpoints[key].status = 'pass';
    
    await window.persistAndRefreshLeadDocuments(l.id, 'checkpoints');
    toast(`<i class="fas fa-check-double" style="color: #34d399; margin-right: 6px;"></i>Document uploaded to <b>${escapeHtml(folderName)}</b> & Checkpoint marked as <b>COMPLETED</b>!`, 'success');
};
var uploadDirectCheckpointDoc = window.uploadDirectCheckpointDoc;

function getFileIconClassAndColor(fileName) {
    const ext = fileName ? fileName.split('.').pop().toLowerCase() : '';
    switch (ext) {
        case 'pdf':
            return { icon: 'far fa-file-pdf', color: '#ef4444' };
        case 'doc':
        case 'docx':
            return { icon: 'far fa-file-word', color: '#3b82f6' };
        case 'xls':
        case 'xlsx':
        case 'csv':
            return { icon: 'far fa-file-excel', color: '#10b981' };
        case 'jpg':
        case 'jpeg':
        case 'png':
        case 'gif':
        case 'svg':
        case 'webp':
            return { icon: 'far fa-file-image', color: '#a855f7' };
        case 'zip':
        case 'rar':
        case '7z':
        case 'tar':
        case 'gz':
            return { icon: 'far fa-file-archive', color: '#eab308' };
        default:
            return { icon: 'far fa-file', color: 'var(--gold)' };
    }
}

function buildAttachmentListHtml(attachments, opts = {}) {
    const list = Array.isArray(attachments) ? attachments : [];
    const { removeFn = null, downloadFn = null, emptyText = 'No files attached.' } = opts;
    if (!list.length) return `<div style="color:var(--text3);font-size:12px;padding:12px 14px;background:rgba(255,255,255,0.01);border:1px dashed rgba(255,255,255,0.04);border-radius:10px;text-align:center;"><i class="fas fa-info-circle" style="opacity:0.5;margin-right:6px;"></i>${emptyText}</div>`;
    return `
        <div class="premium-attachment-grid">
            ${list.map((a, idx) => {
                const decorator = getFileIconClassAndColor(a?.name);
                return `
                <div class="premium-attachment-card">
                    <div class="premium-attachment-details">
                        <i class="${decorator.icon} file-icon" style="color:${decorator.color};"></i>
                        <div class="premium-attachment-info">
                            <div class="premium-attachment-name" title="${escapeHtml(a?.name || `file_${idx + 1}`)}">${escapeHtml(a?.name || `file_${idx + 1}`)}</div>
                            <div class="premium-attachment-size">${formatBytes(a?.size)}${a?.type ? ` • ${escapeHtml(a.type.split('/')[1] || a.type)}` : ''}</div>
                        </div>
                    </div>
                    <div class="premium-attachment-actions">
                        ${downloadFn ? `<button class="premium-attachment-btn download-btn" onclick="${downloadFn}(${idx})" title="Download File"><i class="fas fa-download"></i></button>` : ''}
                        ${removeFn ? `<button class="premium-attachment-btn delete-btn" onclick="${removeFn}(${idx})" title="Remove"><i class="fas fa-trash-alt"></i></button>` : ''}
                    </div>
                </div>
                `;
            }).join('')}
        </div>
    `;
}

function downloadDataUrlAttachment(dataUrl, fileName) {
    if (!dataUrl) {
        toast('Cannot download: File data is empty', 'error');
        return;
    }
    try {
        if (typeof dataUrl === 'string' && dataUrl.startsWith('data:')) {
            const parts = dataUrl.split(',');
            const mimeMatch = parts[0].match(/:(.*?);/);
            const mimeType = mimeMatch ? mimeMatch[1] : 'application/octet-stream';
            const binary = atob(parts[1]);
            const array = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) {
                array[i] = binary.charCodeAt(i);
            }
            const blob = new Blob([array], { type: mimeType });
            const blobUrl = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = blobUrl;
            link.download = fileName || 'download';
            document.body.appendChild(link);
            link.click();
            setTimeout(() => {
                link.remove();
                URL.revokeObjectURL(blobUrl);
            }, 1000);
            return;
        }
    } catch (err) {
        console.warn('Blob download conversion error, falling back to direct anchor:', err);
    }
    const a = document.createElement('a');
    a.href = dataUrl;
    a.download = fileName || 'download';
    document.body.appendChild(a);
    a.click();
    a.remove();
}

window.appendDocText = function(textareaId, text) {
    const el = document.getElementById(textareaId);
    if (!el) return;
    let currentVal = el.value.trim();
    
    // Check if the item already exists in the textarea lines (stripping bullet markers like • or - or * )
    const lines = currentVal.split('\n').map(l => l.replace(/^[•\-\s*]+\s*/, '').trim());
    if (lines.includes(text.trim())) {
        toast(`<i class="fas fa-info-circle" style="color:var(--gold);margin-right:6px;"></i>"${text}" is already listed`, 'info');
        return;
    }
    
    if (currentVal.length > 0) {
        currentVal += '\n• ' + text;
    } else {
        currentVal = '• ' + text;
    }
    el.value = currentVal;
    
    // Dispatch standard input event to trigger any automatic saves or listeners
    el.dispatchEvent(new Event('input'));
    toast(`<i class="fas fa-check-circle" style="color:#4caf50;margin-right:6px;"></i>Added "${text}"`, 'success');
};

