function getEmployeeStagePerformance(userId) {
    const reportData = getDetailedEmployeeReportData(userId);
    const stages = STATUSES.map(s => s.l);
    const values = STATUSES.map(status => {
        const item = reportData.stageSummaryList.find(s => s.stageKey === status.k);
        return item ? (item.avgMs / 3600000) : 0;
    });
    const validValues = values.filter(v => v > 0);
    const avgOverallHours = validValues.length ? (validValues.reduce((a, b) => a + b, 0) / validValues.length) : 0;
    return {
        stages,
        values,
        avgOverallHours,
        avgOverallFormatted: formatHoursLabel(avgOverallHours),
        leadCount: reportData.employeeLeads.length
    };
}

window.empReportStageSortState = { col: 'timesTaken', dir: 'desc' };

function renderEmpReportStageTableHtml(userId, sortCol, sortDir) {
    if (sortCol) window.empReportStageSortState.col = sortCol;
    if (sortDir) window.empReportStageSortState.dir = sortDir;

    const { col, dir } = window.empReportStageSortState;
    const reportData = getDetailedEmployeeReportData(userId);
    let list = [...reportData.stageSummaryList];

    list.sort((a, b) => {
        let valA = a[col];
        let valB = b[col];
        if (typeof valA === 'string') {
            return dir === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        return dir === 'asc' ? ((valA || 0) - (valB || 0)) : ((valB || 0) - (valA || 0));
    });

    const getSortIcon = (headerCol) => {
        if (col !== headerCol) return '<i class="fas fa-sort" style="opacity:0.35; margin-left:4px;"></i>';
        return dir === 'asc' 
            ? '<i class="fas fa-sort-up" style="color:var(--gold); margin-left:4px;"></i>' 
            : '<i class="fas fa-sort-down" style="color:var(--gold); margin-left:4px;"></i>';
    };

    return `
        <table style="width:100%; font-size:12px; border-collapse:collapse; min-width:650px;">
            <thead>
                <tr style="background:rgba(255,255,255,0.05); text-align:left; border-bottom:1px solid var(--border2); user-select:none;">
                    <th onclick="sortEmpReportStageTable('${userId}', 'stageLabel')" style="padding:10px; color:var(--text2); cursor:pointer;" title="Click to sort by Stage Name">
                        Stage Name ${getSortIcon('stageLabel')}
                    </th>
                    <th onclick="sortEmpReportStageTable('${userId}', 'timesTaken')" style="padding:10px; text-align:center; color:var(--text2); cursor:pointer;" title="Click to sort by Times Taken">
                        Times Taken (Cases) ${getSortIcon('timesTaken')}
                    </th>
                    <th onclick="sortEmpReportStageTable('${userId}', 'totalMs')" style="padding:10px; color:var(--text2); cursor:pointer;" title="Click to sort by Total Time Taken">
                        Total Time Taken ${getSortIcon('totalMs')}
                    </th>
                    <th onclick="sortEmpReportStageTable('${userId}', 'avgMs')" style="padding:10px; color:var(--text2); cursor:pointer;" title="Click to sort by Average Time">
                        Average Time / Step ${getSortIcon('avgMs')}
                    </th>
                    <th onclick="sortEmpReportStageTable('${userId}', 'minMs')" style="padding:10px; color:var(--text2); cursor:pointer;" title="Click to sort by Min Step Time">
                        Min Step Time ${getSortIcon('minMs')}
                    </th>
                    <th onclick="sortEmpReportStageTable('${userId}', 'maxMs')" style="padding:10px; color:var(--text2); cursor:pointer;" title="Click to sort by Max Step Time">
                        Max Step Time ${getSortIcon('maxMs')}
                    </th>
                </tr>
            </thead>
            <tbody>
                ${list.map(st => `
                    <tr style="border-bottom:1px solid rgba(255,255,255,0.03);">
                        <td style="padding:8px 10px;"><strong>${escapeHtml(st.stageLabel)}</strong></td>
                        <td style="padding:8px 10px; text-align:center;">
                            <span class="badge ${st.timesTaken > 0 ? 'badge-primary' : 'badge-ghost'}" style="font-size:11px; font-weight:700;">${st.timesTaken} times</span>
                        </td>
                        <td style="padding:8px 10px; color:#fff;">${st.totalFormatted}</td>
                        <td style="padding:8px 10px;"><strong style="color:var(--gold);">${st.avgFormatted}</strong></td>
                        <td style="padding:8px 10px; color:var(--text2);">${st.minFormatted}</td>
                        <td style="padding:8px 10px; color:var(--text2);">${st.maxFormatted}</td>
                    </tr>
                `).join('')}
            </tbody>
        </table>
    `;
}

function sortEmpReportStageTable(userId, sortCol) {
    if (!window.empReportStageSortState) window.empReportStageSortState = { col: 'timesTaken', dir: 'desc' };
    if (window.empReportStageSortState.col === sortCol) {
        window.empReportStageSortState.dir = window.empReportStageSortState.dir === 'asc' ? 'desc' : 'asc';
    } else {
        window.empReportStageSortState.col = sortCol;
        window.empReportStageSortState.dir = (sortCol === 'stageLabel') ? 'asc' : 'desc';
    }
    const container = document.getElementById('empReportStageTableContainer');
    if (container) {
        container.innerHTML = renderEmpReportStageTableHtml(userId);
    }
}

