async function saveMoveUserDept(userId) {
    const targetDept = document.getElementById('moveTargetDepartment')?.value;
    const newDesignation = document.getElementById('moveNewDesignation')?.value.trim();

    if (!targetDept) {
        toast('Please select target department', 'error');
        return;
    }

    const user = users.find(u => u.userId === userId);
    if (!user) return;

    user.department = targetDept;
    if (newDesignation) user.designation = newDesignation;

    if (usersRef) {
        await usersRef.child(userId).update({ department: targetDept, designation: user.designation });
    }
    saveLocalTableItem('users', userId, user);
    if (typeof window.saveLocalState === 'function') window.saveLocalState();

    toast(`Transferred ${user.displayName} to ${getDepartmentName(targetDept)}`, 'success');
    closeModal();
    if (currentPage === 'admin-panel') renderAdminPanel();
}

