window.switchPermModalTab = function(tabName) {
    document.querySelectorAll('.perm-modal-tab-pane').forEach(el => el.style.display = 'none');
    const isLight = document.documentElement.getAttribute('data-theme') === 'theme-light';
    document.querySelectorAll('.perm-tab-btn').forEach(btn => {
        btn.classList.remove('active');
        btn.style.setProperty('background', isLight ? '#f1f5f9' : 'var(--surface2, #1e2238)', 'important');
        btn.style.setProperty('color', isLight ? '#0f172a' : 'var(--text2, #cbd5e1)', 'important');
        btn.style.setProperty('border', isLight ? '1.5px solid #cbd5e1' : '1px solid var(--border2, rgba(223, 178, 87, 0.25))', 'important');
        btn.style.setProperty('font-weight', '700', 'important');
        btn.style.setProperty('box-shadow', 'none', 'important');
        const icon = btn.querySelector('i');
        if (icon) icon.style.setProperty('color', isLight ? '#64748b' : 'var(--gold, #dfb257)', 'important');
    });

    const targetPane = document.getElementById(`permPane_${tabName}`);
    const targetBtn = document.getElementById(`permTabBtn_${tabName}`);
    if (targetPane) targetPane.style.display = 'block';
    if (targetBtn) {
        targetBtn.classList.add('active');
        targetBtn.style.setProperty('background', 'var(--gold, #dfb257)', 'important');
        targetBtn.style.setProperty('color', '#000000', 'important');
        targetBtn.style.setProperty('border', '2px solid var(--gold, #dfb257)', 'important');
        targetBtn.style.setProperty('font-weight', '800', 'important');
        targetBtn.style.setProperty('box-shadow', '0 2px 10px rgba(223, 178, 87, 0.35)', 'important');
        const icon = targetBtn.querySelector('i');
        if (icon) icon.style.setProperty('color', '#000000', 'important');
    }
};

window.toggleAllPermPages = function(selectAll) {
    const container = document.getElementById('permPages');
    if (!container) return;
    const checkboxes = container.querySelectorAll('input[type="checkbox"]');
    checkboxes.forEach(cb => {
        cb.checked = !!selectAll;
        cb.closest('.premium-checkbox-card')?.classList.toggle('checked', !!selectAll);
    });
    window.updatePermPagesCountBadge();
};

window.updatePermPagesCountBadge = function() {
    const container = document.getElementById('permPages') || document.getElementById('newUserPagesGrid');
    if (!container) return;
    const count = container.querySelectorAll('input[type="checkbox"]:checked').length;
    const badgeNum = document.getElementById('permPagesCountNum') || document.getElementById('newUserPagesCountNum');
    if (badgeNum) badgeNum.innerText = count;
};

window.resetPermPagesToRoleDefault = function(role) {
    const targetRole = role || document.getElementById('permRole')?.value || 'cso';
    const defaults = getDefaultPermissions(targetRole);
    const container = document.getElementById('permPages');
    if (!container) return;

    container.querySelectorAll('input[type="checkbox"]').forEach(cb => {
        const isAllowed = defaults.pageAccess.includes(cb.value);
        cb.checked = isAllowed;
        cb.closest('.premium-checkbox-card')?.classList.toggle('checked', isAllowed);
    });
    window.updatePermPagesCountBadge();
    toast(`Reset modules to default access for ${targetRole.replace(/_/g, ' ').toUpperCase()}`, 'info');
};

