async function saveUserPermissions(userId) {
    const displayName = document.getElementById('permDisplayName')?.value.trim();
    const email = document.getElementById('permEmail')?.value.trim();
    const phone = document.getElementById('permPhone')?.value.trim();
    const role = document.getElementById('permRole')?.value;
    const department = document.getElementById('permDepartment')?.value;
    const designation = document.getElementById('permDesignation')?.value.trim();
    const status = document.getElementById('permStatus')?.value || 'active';

    if (!displayName || !role) {
        toast('Please fill in display name and role', 'error');
        return;
    }

    // Extract all granular action permissions from the form
    const selectedPages = [...document.querySelectorAll('#permPages input[type="checkbox"]:checked')].map(cb => cb.value);

    // Harmonize Dump Store and Data Center based on explicit selection
    const canManageDumpStore = selectedPages.includes('dump-store') && !!document.getElementById('perm_canManageDumpStore')?.checked;
    const canManageDataCenter = selectedPages.includes('data-center') && !!document.getElementById('perm_canManageDataCenter')?.checked;

    const permissions = {
        // Module Page Access
        pageAccess: selectedPages,

        // Lead operations
        canViewLeads: !!document.getElementById('perm_canViewLeads')?.checked,
        canCreateLeads: !!document.getElementById('perm_canCreateLeads')?.checked,
        canEditLeads: !!document.getElementById('perm_canEditLeads')?.checked,
        canDeleteLeads: !!document.getElementById('perm_canDeleteLeads')?.checked,
        canApproveLeads: !!document.getElementById('perm_canApproveLeads')?.checked,
        canRejectLeads: !!document.getElementById('perm_canRejectLeads')?.checked,
        canAssignLeads: !!document.getElementById('perm_canAssignLeads')?.checked,

        // Enquiry operations
        canViewEnquiries: !!document.getElementById('perm_canViewEnquiries')?.checked,
        canCreateEnquiries: !!document.getElementById('perm_canCreateEnquiries')?.checked,
        canEditEnquiries: !!document.getElementById('perm_canEditEnquiries')?.checked,
        canDeleteEnquiries: !!document.getElementById('perm_canDeleteEnquiries')?.checked,
        canConvertEnquiries: !!document.getElementById('perm_canConvertEnquiries')?.checked,

        // Processing & documents
        canManageProcessing: !!document.getElementById('perm_canManageProcessing')?.checked,
        canUploadDocuments: !!document.getElementById('perm_canUploadDocuments')?.checked,
        canDeleteDocuments: !!document.getElementById('perm_canDeleteDocuments')?.checked,

        // Legal documents & queries
        canManageLegalQueries: !!document.getElementById('perm_canManageLegalQueries')?.checked,
        canManageLegalDocs: !!document.getElementById('perm_canManageLegalDocs')?.checked,
        canAccessAllSecuredAndMSME: !!document.getElementById('perm_canAccessAllSecuredAndMSME')?.checked,
        canAccessAllLegalLeads: !!document.getElementById('perm_canAccessAllLegalLeads')?.checked,
        canAccessAllFolders: !!document.getElementById('perm_canAccessAllFolders')?.checked,

        // Tasks, reminders, escalations
        canManageTasks: !!document.getElementById('perm_canManageTasks')?.checked,
        canManageReminders: !!document.getElementById('perm_canManageReminders')?.checked,
        canManageEscalations: !!document.getElementById('perm_canManageEscalations')?.checked,

        // Data, store & admin
        canExportData: !!document.getElementById('perm_canExportData')?.checked,
        canManageDumpStore: canManageDumpStore,
        canManageDataCenter: canManageDataCenter,
        canManageUsers: !!document.getElementById('perm_canManageUsers')?.checked
    };

    const existingUser = users.find(u => u.userId === userId) || {};
    const fullUserRecord = {
        ...existingUser,
        displayName,
        email,
        phone,
        role,
        department,
        designation,
        status,
        permissions,
        userId: userId
    };

    // 1. Direct Supabase Cloud DB write - fully awaited to prevent losing data on refresh
    if (sb && !supabaseSetupRequired) {
        try {
            const now = new Date().toISOString();
            await sb.from('users').upsert({ id: userId, data: fullUserRecord, updated_at: now });
            console.log(`✅ [Supabase] Permissions for @${userId} successfully synced to cloud`);
        } catch (e) {
            console.warn('[Supabase saveUserPermissions notice]:', e);
        }
    }
    if (usersRef) {
        try {
            await usersRef.child(userId).set(fullUserRecord);
        } catch (e) {
            console.warn('[usersRef saveUserPermissions notice]:', e);
        }
    }

    // 2. Update in-memory caches & arrays
    tableMemoryCache.users = tableMemoryCache.users || {};
    tableMemoryCache.users[userId] = fullUserRecord;
    saveLocalTableItem('users', userId, fullUserRecord);

    const uIdx = users.findIndex(u => u.userId === userId);
    if (uIdx !== -1) {
        users[uIdx] = fullUserRecord;
    } else {
        users.push(fullUserRecord);
    }

    // 3. Synchronously flush to localStorage
    if (typeof flushLocalStateSync === 'function') flushLocalStateSync();

    // 4. Persist to server backend API so /data/users.json is immediately updated
    try {
        await fetch('/api/users', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ users })
        }).catch(e => console.warn('API users sync notice:', e));
    } catch(e) {}

    // 3. Broadcast permission update event across session & cross-tab storage
    try {
        localStorage.setItem('crm_user_perms_broadcast', JSON.stringify({
            userId,
            permissions,
            status,
            role,
            displayName,
            ts: Date.now()
        }));
    } catch(e) {}
    window.dispatchEvent(new CustomEvent('crm-permissions-updated', {
        detail: { userId, permissions, status, role, displayName }
    }));

    toast(`<i class="fas fa-check-circle" style="color:#4caf50;margin-right:6px;"></i>Permissions for <b>${escapeHtml(displayName)}</b> updated successfully`, 'success');
    closeModal();

    if (currentPage === 'admin-panel') renderAdminPanel(adminActiveTab);

    // 4. If current active session is the user being modified, immediately synchronize live UI!
    if (currentUser?.userId === userId) {
        currentUser = { ...currentUser, ...fullUserRecord };
        sessionStorage.setItem('crmUser', JSON.stringify(currentUser));
        updateTopbarUserChip();
        buildSidebar();

        // If user is currently viewing a module they no longer have permission to view, redirect to authorized landing page
        if (!canViewPage(currentPage)) {
            toast('Your access permissions have been updated. Redirecting to authorized section...', 'warning');
            const landing = getRoleLandingPage(currentUser.role, currentUser.permissions);
            navToPage(landing);
        } else if (typeof loadPage === 'function') {
            loadPage(currentPage);
        }
    }
}
window.openEditUserPermissions = openEditUserPermissions;
window.saveUserPermissions = saveUserPermissions;

window.deleteCrmUser = async function(userId) {
    if (!userId) return;
    if (userId === 'admin_1' || (currentUser && currentUser.userId === userId)) {
        toast('Cannot delete primary executive admin or active login session', 'warning');
        return;
    }
    const targetUser = users.find(u => u.userId === userId);
    if (!targetUser) {
        toast('User account not found', 'error');
        return;
    }
    if (!confirm('Are you sure you want to permanently remove "' + targetUser.displayName + '" (@' + userId + ') from the CRM?')) {
        return;
    }
    users = users.filter(u => u.userId !== userId);
    if (Array.isArray(departments)) {
        departments.forEach(dept => {
            if (dept.headId === userId) {
                dept.headId = '';
                if (departmentsRef) {
                    departmentsRef.child(dept.id).update({ headId: '' });
                }
            }
        });
    }
    if (usersRef) {
        await usersRef.child(userId).remove();
    }
    saveLocalTableItem('users', userId, null);
    if (typeof persistLocalState === 'function') {
        persistLocalState();
    }
    if (typeof window.saveLocalState === 'function') {
        window.saveLocalState();
    }
    toast('User "' + targetUser.displayName + '" removed successfully', 'success');
    renderAdminPanel(adminActiveTab);
};

async function toggleUserStatus(userId) {
    const user = users.find(u => u.userId === userId);
    if (!user) return;

    const newStatus = user.status === 'deactivated' ? 'active' : 'deactivated';
    const actionLabel = newStatus === 'active' ? 'Activated' : 'Deactivated';

    user.status = newStatus;
    if (usersRef) {
        await usersRef.child(userId).update({ status: newStatus });
    }
    saveLocalTableItem('users', userId, user);
    if (typeof window.saveLocalState === 'function') window.saveLocalState();

    toast(`Account for ${user.displayName} is now ${actionLabel}`, newStatus === 'active' ? 'success' : 'warning');
    if (currentPage === 'admin-panel') renderAdminPanel();
}

