async function saveCreateDepartment() {
    const name = document.getElementById('newDeptName')?.value.trim();
    const code = document.getElementById('newDeptCode')?.value.trim().toUpperCase();
    const description = document.getElementById('newDeptDesc')?.value.trim();
    const color = document.getElementById('newDeptColor')?.value || '#f59e0b';
    const icon = document.getElementById('newDeptIcon')?.value || 'fa-building';

    if (!name || !code) {
        toast('Department Name and Code are required', 'error');
        return;
    }

    const deptId = code.toLowerCase().replace(/[^a-z0-9]/g, '_');
    if (departments.some(d => d.id === deptId || d.code === code)) {
        toast('Department with this ID or Code already exists', 'error');
        return;
    }

    const newDept = {
        id: deptId,
        name,
        code,
        description: description || 'Enterprise business department.',
        headId: null,
        icon,
        color,
        status: 'active',
        createdAt: new Date().toISOString()
    };

    if (departmentsRef) {
        await departmentsRef.child(deptId).set(newDept);
    }
    saveLocalTableItem('departments', deptId, newDept);
    departments.push(newDept);
    if (typeof window.saveLocalState === 'function') window.saveLocalState();

    toast(`Department "${name}" created successfully`, 'success');
    closeModal();
    if (currentPage === 'admin-panel') renderAdminPanel();
}

