// ===================== NAVIGATION =====================
function navToPage(page, options = {}) {
    if (!page) return;
    if (page === 'follow-up') page = 'followup';
    if (typeof syncCurrentUserFromUsers === 'function') syncCurrentUserFromUsers();
    if (page === currentPage && !options.force) return;
    if (!canViewPage(page)) {
        toast('Access denied', 'error');
        return;
    }
    // If a modal was open, close all modals so user sees the target page cleanly
    const overlayEl = document.getElementById('overlay');
    if (overlayEl && (overlayEl.classList.contains('open') || overlayEl.classList.contains('show'))) {
        closeAllModals();
    }
    currentPage = page;
    loadPage(page);
    updateSidebarActive();
    
    if (!options.fromHistory) {
        if (window.history && window.history.pushState) {
            window.history.pushState({ type: 'page', page: page }, '', '#' + page);
        } else {
            window.location.hash = page;
        }
    }
}

function updateSidebarActive() {
    document.querySelectorAll('.sb-item').forEach(el => el.classList.remove('active'));
    const active = document.querySelector(`.sb-item[data-page="${currentPage}"]`);
    if (active) active.classList.add('active');
}

