window.updateTopbarUserChip = function() {
    if (!currentUser) return;
    const nameEl = document.getElementById('topbarUserName');
    const roleEl = document.getElementById('topbarUserRole');
    const avatarEl = document.getElementById('topbarUserAvatar');
    const chipEl = document.getElementById('topbarUserChip');
    if (nameEl) nameEl.innerText = currentUser.displayName || currentUser.userId || 'User';
    if (roleEl) roleEl.innerText = (currentUser.role || 'USER').toUpperCase().replace('_', ' ');
    if (chipEl) chipEl.title = `${currentUser.displayName || 'Admin'} (${(currentUser.role || 'ADMIN').toUpperCase()})`;
    if (avatarEl) {
        avatarEl.innerHTML = currentUser.role === 'admin' ? '<i class="fas fa-user-shield"></i>' : '<i class="fas fa-user"></i>';
    }
};

window.togglePasswordVisibility = function() {
    const pwdInput = document.getElementById('loginPassword');
    const eyeIcon = document.getElementById('pwdEyeIcon');
    if (pwdInput && eyeIcon) {
        if (pwdInput.type === 'password') {
            pwdInput.type = 'text';
            eyeIcon.classList.remove('fa-eye');
            eyeIcon.classList.add('fa-eye-slash');
        } else {
            pwdInput.type = 'password';
            eyeIcon.classList.remove('fa-eye-slash');
            eyeIcon.classList.add('fa-eye');
        }
    }
};

// ===================== SEARCH =====================
window.handleGlobalSearch = function(val) {
    searchQuery = (val || '').toLowerCase().trim();
    if (currentPage === 'all-leads') renderAllLeads();
    else if (currentPage === 'new-leads') renderNewLeads();
    else if (currentPage === 'followup' || currentPage === 'follow-up') renderFollowUpPage();
    else if (currentPage === 'processing') renderProcessing();
    else if (currentPage === 'tat-breach') renderTatBreach();
    else if (currentPage === 'tat-warning') renderTatWarning();
    else if (currentPage === 'enquiries') {
        const el = document.getElementById('enquirySearchInput');
        if (el) el.value = val;
        renderEnquiries();
    }
    else if (currentPage === 'dump-store') {
        const el = document.getElementById('dumpSearchInput');
        if (el) el.value = val;
        renderDumpStore();
    }
    else if (currentPage === 'data-center') {
        const el = document.getElementById('dcSearchInput');
        if (el) el.value = val;
        renderDataCenter();
    }
    else if (currentPage === 'pipeline') {
        if (window.updatePipelineFilter) window.updatePipelineFilter('search', val);
    }
    else if (currentPage === 'reminders') renderReminders();
    else if (currentPage === 'tasks') renderTasks();
};

window.triggerGlobalSearch = function() {
    const searchInput = document.getElementById('searchInput');
    const val = searchInput ? searchInput.value.trim() : searchQuery;
    window.handleGlobalSearch(val);
    if (val && !['all-leads', 'new-leads', 'followup', 'follow-up', 'processing', 'tat-breach', 'tat-warning', 'enquiries', 'dump-store', 'data-center', 'pipeline', 'reminders', 'tasks'].includes(currentPage)) {
        navToPage('all-leads');
    }
};

function setupSearch() {
    const searchInput = document.getElementById('searchInput');
    if (!searchInput) return;

    searchInput.addEventListener('input', (e) => {
        window.handleGlobalSearch(e.target.value);
    });

    searchInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            window.triggerGlobalSearch();
        }
    });

    const searchIcon = document.querySelector('.search-wrap .search-icon');
    if (searchIcon) {
        searchIcon.style.cursor = 'pointer';
        searchIcon.title = 'Click to filter';
        searchIcon.onclick = window.triggerGlobalSearch;
    }

    // Keyboard shortcut Cmd/Ctrl + K to focus search
    document.addEventListener('keydown', (e) => {
        if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
            e.preventDefault();
            searchInput.focus();
            searchInput.select();
        }
    });
}

function refreshCurrentPage() {
    if (!currentPage) return;

    if (currentPage === 'dashboard') {
        renderDashboard();
    } else if (currentPage === 'all-leads') {
        renderAllLeads();
    } else if (currentPage === 'new-leads') {
        renderNewLeads();
    } else if (currentPage === 'followup' || currentPage === 'follow-up') {
        renderFollowUpPage();
    } else if (currentPage === 'processing') {
        renderProcessing();
    } else if (currentPage === 'tat-breach') {
        renderTatBreach();
    } else if (currentPage === 'tat-warning') {
        renderTatWarning();
    } else if (currentPage === 'reminders') {
        renderReminders();
    } else if (currentPage === 'tasks') {
        renderTasks();
    } else if (currentPage === 'escalations') {
        renderEscalations();
    } else if (currentPage === 'reports') {
        renderReports();
    } else if (currentPage === 'pipeline') {
        renderPipeline();
    } else if (currentPage === 'lead-details' && currentLeadId) {
        viewLead(currentLeadId);
    } else if (currentPage === 'workflow') {
        // static
    } else {
        loadPage(currentPage);
    }

    if (typeof updateBadges === 'function') updateBadges();
}
window.refreshCurrentPage = refreshCurrentPage;

// ===================== FIREBASE REAL-TIME LISTENERS =====================
function initRealtime() {
    if (!firebaseEnabled) {
        updateBadges();
        updateNotificationBadge();
        return;
    }

    if (leadsRef) {
        leadsRef.on('value', snap => {
            const leadData = snap.val() || {};
            leads = Object.entries(leadData)
                .map(([id, v]) => ({ id, ...(typeof v === 'object' && v !== null ? v : {}) }))
                .filter(l => l && l.name && l.name !== 'undefined' && String(l.name).trim() !== '');
            refreshCurrentPage();
            updateNotificationBadge();
        });
    }

    if (enquiriesRef) {
        enquiriesRef.on('value', snap => {
            const enqData = snap.val() || {};
            enquiries = Object.entries(enqData)
                .map(([id, v]) => ({ id, ...(typeof v === 'object' && v !== null ? v : {}) }))
                .filter(e => !isDummyEnquiry(e));
            if (currentPage === 'enquiries') renderEnquiries();
            else if (currentPage === 'dump-store') renderDumpStore();
            else if (currentPage === 'data-center') renderDataCenter();
            updateBadges();
        });
    }

    if (usersRef) {
        usersRef.on('value', snap => {
            const userData = snap.val() || {};
            users = Object.entries(userData).map(([id, v]) => normalizeUser({ userId: id, ...v }));
            if (currentUser) {
                const refreshedMe = users.find(u => u.userId === currentUser.userId);
                if (refreshedMe) {
                    const statusChanged = refreshedMe.status !== currentUser.status;
                    const permsChanged = JSON.stringify(refreshedMe.permissions) !== JSON.stringify(currentUser.permissions);
                    currentUser = { ...currentUser, ...refreshedMe };
                    sessionStorage.setItem('crmUser', JSON.stringify(currentUser));
                    if (statusChanged && (currentUser.status === 'deactivated' || currentUser.status === 'inactive' || currentUser.active === false)) {
                        toast('Your account has been deactivated by the Administrator. Logging out...', 'error');
                        setTimeout(logout, 1500);
                        return;
                    }
                    if (permsChanged) {
                        updateTopbarUserChip();
                        buildSidebar();
                        if (!canViewPage(currentPage)) {
                            toast('Your access permissions were updated by Administrator. Redirecting...', 'warning');
                            const landing = getRoleLandingPage(currentUser.role, currentUser.permissions);
                            navToPage(landing);
                        } else if (typeof refreshCurrentPage === 'function') {
                            refreshCurrentPage();
                        }
                    }
                }
            }
            if (currentPage === 'admin-panel' && typeof renderAdminPanel === 'function') {
                renderAdminPanel(typeof adminActiveTab !== 'undefined' ? adminActiveTab : undefined);
            }
        });
    }

    if (departmentsRef) {
        departmentsRef.on('value', snap => {
            const deptData = snap.val() || {};
            if (Array.isArray(deptData) && deptData.length) {
                departments = deptData;
            } else if (typeof deptData === 'object' && Object.keys(deptData).length) {
                departments = Object.values(deptData);
            }
        });
    }

    if (remindersRef) {
        remindersRef.on('value', snap => {
            const reminderData = snap.val() || {};
            reminders = Object.entries(reminderData).map(([id, v]) => ({ id, ...v }));
            if (currentPage === 'reminders') renderReminders();
            updateBadges();
        });
    }

    if (tasksRef) {
        tasksRef.on('value', snap => {
            const taskData = snap.val() || {};
            tasks = Object.entries(taskData).map(([id, v]) => ({ id, ...v }));
            if (currentPage === 'tasks') renderTasks();
            updateBadges();
        });
    }

    if (escalationsRef) {
        escalationsRef.on('value', snap => {
            const escalationData = snap.val() || {};
            escalations = Object.entries(escalationData).map(([id, v]) => ({ id, ...v }));
            if (currentPage === 'escalations') renderEscalations();
            updateBadges();
        });
    }

    if (loanTypesRef) {
        loanTypesRef.on('value', snap => {
            const loanTypeData = snap.val() || {};
            loanTypes = Array.isArray(loanTypeData) ? loanTypeData.filter(Boolean) : Object.values(loanTypeData).filter(Boolean);
        });
    }
}

// ===================== HELPER FORMATTING =====================
function formatNumberIndian(val) {
    if (val === null || val === undefined || val === '') return '0';
    const num = Number(val);
    if (isNaN(num)) return String(val);
    return num.toLocaleString('en-IN');
}

// ===================== LEAD DETAIL MODAL WITH FULL DATA TABS =====================
async function viewLead(id) {
    try {
        if (typeof clearPreviousLeadState === 'function') {
            clearPreviousLeadState();
        }

        if (window.CrmIndexedDBCache && typeof window.CrmIndexedDBCache.recordLeadAccess === 'function') {
            window.CrmIndexedDBCache.recordLeadAccess(id);
        }

        let l = null;
        let memLead = null;
        if (typeof tableMemoryCache !== 'undefined' && tableMemoryCache.leads && tableMemoryCache.leads[id]) {
            memLead = tableMemoryCache.leads[id];
        }
        if (!memLead && Array.isArray(leads)) {
            memLead = leads.find(x => String(x.id) === String(id) || x.id === id);
        }

        // Check IndexedDB for lead
        let dbLead = null;
        if (window.CrmIndexedDBCache && typeof window.CrmIndexedDBCache.getLead === 'function') {
            try {
                dbLead = await window.CrmIndexedDBCache.getLead(id);
            } catch (e) {
                console.warn('Error fetching fresh lead from IndexedDB:', e);
            }
        }

        if (memLead && dbLead) {
            // Merge, ensuring newest attachments, checkpoints, and documents are never dropped
            l = { ...dbLead, ...memLead };
            const memAtts = Array.isArray(memLead.attachments) ? memLead.attachments : [];
            const dbAtts = Array.isArray(dbLead.attachments) ? dbLead.attachments : [];
            const mergedAttsMap = new Map();
            dbAtts.forEach(a => {
                if (a && a.name) mergedAttsMap.set(a.name, a);
            });
            memAtts.forEach(a => {
                if (a && a.name) {
                    if (mergedAttsMap.has(a.name)) {
                        const prev = mergedAttsMap.get(a.name);
                        mergedAttsMap.set(a.name, {
                            ...prev,
                            ...a,
                            dataUrl: a.dataUrl || prev.dataUrl || ''
                        });
                    } else {
                        mergedAttsMap.set(a.name, a);
                    }
                }
            });
            l.attachments = Array.from(mergedAttsMap.values());
            l.checkpoints = { ...(dbLead.checkpoints || {}), ...(memLead.checkpoints || {}) };
            l.documents = { ...(dbLead.documents || {}), ...(memLead.documents || {}) };
        } else {
            l = memLead || dbLead;
        }

        if (l) {
            // Keep in-memory cache and leads array in sync with latest lead object
            if (typeof tableMemoryCache !== 'undefined') {
                tableMemoryCache.leads = tableMemoryCache.leads || {};
                tableMemoryCache.leads[id] = l;
            }
            if (Array.isArray(leads)) {
                const lIdx = leads.findIndex(x => x.id === id);
                if (lIdx >= 0) leads[lIdx] = l;
                else leads.push(l);
            }
        }

        if (!l) {
            // Check if ID is an accounts record ID or referenced in accounts records
            if (Array.isArray(window.accountsRecords)) {
                let acc = window.accountsRecords.find(a => a.id === id || a.leadId === id);
                if (acc) {
                    // Try to match lead by customerName or phone
                    if (acc.leadId) {
                        l = (leads || []).find(x => x.id === acc.leadId);
                    }
                    if (!l && acc.customerName) {
                        const targetName = String(acc.customerName).toLowerCase().trim();
                        l = (leads || []).find(x => x.name && String(x.name).toLowerCase().trim() === targetName);
                    }
                    if (!l && acc.phone) {
                        l = (leads || []).find(x => x.phone && String(x.phone).trim() === String(acc.phone).trim());
                    }
                    if (!l) {
                        // Create lead object from account record
                        l = {
                            id: acc.leadId || acc.id || id,
                            name: acc.customerName || 'Disbursed Client',
                            phone: acc.phone || '',
                            email: acc.email || '',
                            amount: acc.loanAmount || 0,
                            loanType: acc.loanProduct || 'Loan',
                            bank: acc.bankName || '',
                            status: 'disbursed',
                            category: acc.category || 'MSME',
                            accountsData: acc,
                            createdAt: acc.disbursementDate || new Date().toISOString(),
                            history: [
                                {
                                    action: 'Disbursed',
                                    status: 'disbursed',
                                    date: acc.disbursementDate || new Date().toISOString(),
                                    user: 'Accounts',
                                    notes: `Disbursed loan recorded in Accounts. Bank: ${acc.bankName || 'N/A'}. Payout: ${acc.payoutPercentage || 0}%.`
                                }
                            ]
                        };
                        if (Array.isArray(leads)) {
                            leads.push(l);
                        }
                    }
                }
            }
        }

        if (!l) {
            const e = (enquiries || []).find(x => x.id === id);
            if (e && typeof openAddEnquiry === 'function') {
                openAddEnquiry(id);
                return;
            }
            if (typeof toast === 'function') {
                toast('Lead record not found in system', 'warning');
            }
            return;
        }
        if (!canUserViewLead(l, currentUser)) {
            if (typeof toast === 'function') toast('Access restricted: You do not have permission to view this lead', 'warning');
            return;
        }
        currentLeadId = id;
        window.currentViewingLeadId = id;
        window.leadInfoEditMode = window.leadInfoEditMode || {};
        window.leadInfoEditMode[id] = false;
        if (typeof markLeadAsRead === 'function') {
            markLeadAsRead(id);
        }
        // Initialize partner state strictly for this verified lead
        if (typeof getVerifiedPartnerNames === 'function') {
            window.docCheckPointsPartnerNames = JSON.parse(JSON.stringify(getVerifiedPartnerNames(l)));
            window.currentDocCheckPointsMemberCount = (typeof getVerifiedMemberCount === 'function') ? getVerifiedMemberCount(l) : 0;
        } else {
            window.docCheckPointsPartnerNames = (l.partnerNames && typeof l.partnerNames === 'object') ? JSON.parse(JSON.stringify(l.partnerNames)) : {};
            window.currentDocCheckPointsMemberCount = parseInt(l.partnersCount || l.noOfPartners || l.directorsCount || 0) || 0;
        }
        renderLeadModal(l);
    } catch (err) {
        console.error('Error opening lead:', err);
        if (typeof toast === 'function') toast('Failed to open lead details: ' + (err.message || err), 'error');
    }
}

function formatTime(timestamp) {
    if (!timestamp) return 'Unknown';
    const date = new Date(timestamp);
    if (isNaN(date.getTime())) return timestamp;
    return date.toLocaleString();
}

// ===================== LEAD DUMP SECTION CARD & TAB =====================
function getDumpDataForLead(l) {
    if (!l) return { dumpDate: 'N/A', source: 'Follow Up', actor: 'Admin', category: 'Not Feasible', detailedRemarks: 'Lead moved to Dump Store', fullReason: 'Dumped' };
    
    let dumpDate = 'N/A';
    if (l.rejectedAt || l.dumpedAt) {
        dumpDate = safeFormatDateTime(l.rejectedAt || l.dumpedAt);
    } else if (Array.isArray(l.history)) {
        const rejHist = [...l.history].reverse().find(h => h && h.action && (h.action.toLowerCase().includes('reject') || h.action.toLowerCase().includes('dump')));
        if (rejHist && (rejHist.timestamp || rejHist.date || rejHist.time || rejHist.d)) {
            dumpDate = safeFormatDateTime(rejHist.timestamp || rejHist.date || rejHist.time || rejHist.d);
        }
    }
    if (dumpDate === 'N/A') {
        dumpDate = safeFormatDateTime(l.updatedAt || l.createdAt || Date.now());
    }

    let source = l.rejectedFrom || l.previousStage;
    let actor = l.rejectedBy || l.dumpedBy || '';
    if (Array.isArray(l.history)) {
        const rejHist = [...l.history].reverse().find(h => h && h.action && (h.action.toLowerCase().includes('reject') || h.action.toLowerCase().includes('dump')));
        if (rejHist) {
            if (!source) source = rejHist.prevStatus || rejHist.from || rejHist.source;
            if (!actor) actor = rejHist.by || rejHist.user;
        }
    }
    if (!source) source = 'Follow Up Store';
    if (!actor) actor = currentUser?.displayName || 'Admin';

    const dumpDetails = l.dumpDetails || {};
    const reasonText = l.rejectionReason || l.dumpReason || dumpDetails.reason || 'Customer Not Interested / Cancelled';
    const category = dumpDetails.category || l.rejectionCategory || (reasonText.includes(' - ') ? reasonText.split(' - ')[0].trim() : reasonText.trim());
    let detailedRemarks = dumpDetails.remarks || (reasonText.includes(' - ') ? reasonText.split(' - ').slice(1).join(' - ').trim() : (l.remarks || ''));
    if (detailedRemarks && category && detailedRemarks.trim().toLowerCase() === category.trim().toLowerCase()) {
        detailedRemarks = '';
    }

    return { dumpDate, source, actor, category, detailedRemarks, fullReason: reasonText };
}

