function openCreateReminder() {
    const depts = [...new Set(users.map(u => u.department).filter(d => d))];
    if (!depts.length) depts.push('CSO', 'Operations', 'Credit');
    const leadOptions = leads.map(l => `<option value="${escapeHtml(l.id)}">${escapeHtml(l.name)} (${escapeHtml(l.loanType)})</option>`).join('');
    const userOptions = users.map(u => `<option value="${escapeHtml(u.userId)}">${escapeHtml(u.displayName)}</option>`).join('');
    const ccOptions = users.map(u => `
        <label class="checkbox-chip">
            <input type="checkbox" value="${escapeHtml(u.userId)}">
            <span class="chip-label">${escapeHtml(u.displayName)}</span>
        </label>
    `).join('');

    openModal('<i class="fas fa-bell text-gold mr-2"></i> Create Reminder', `
        <div class="fg">
            <label><i class="fas fa-heading"></i> Reminder Title</label>
            <input id="remTitle" placeholder="e.g. Client verification call">
        </div>
        <div class="fg">
            <label><i class="fas fa-align-left"></i> Description</label>
            <textarea id="remDesc" rows="2" placeholder="Details about this reminder..."></textarea>
        </div>
        <div class="fg-grid">
            <div class="fg">
                <label><i class="far fa-calendar-alt"></i> Due Date</label>
                <input type="date" id="remDue">
            </div>
            <div class="fg">
                <label><i class="fas fa-folder"></i> Related Lead</label>
                <select id="remLead">
                    <option value="">None (General)</option>
                    ${leadOptions}
                </select>
            </div>
        </div>
        <div class="fg-grid">
            <div class="fg">
                <label><i class="fas fa-sitemap"></i> Type</label>
                <select id="remType" onchange="toggleReminderAssign(this.value)">
                    <option value="person">Person-wise</option>
                    <option value="department">Department-wise</option>
                    <option value="custom">Custom Selection</option>
                </select>
            </div>
            <div id="remAssignArea" class="fg">
                <label><i class="fas fa-user-check"></i> Select Person</label>
                <select id="remPerson">${userOptions}</select>
            </div>
        </div>
        <div class="fg">
            <label><i class="fas fa-eye"></i> Monitor (CC Users)</label>
            <div id="remCc" class="checkbox-grid">
                ${ccOptions}
            </div>
        </div>
    `, `
        <button class="btn btn-ghost" onclick="closeModal()">Cancel</button>
        <button class="btn btn-primary" onclick="saveReminder()"><i class="fas fa-bell"></i> Set Reminder</button>
    `, 'md');

    window.toggleReminderAssign = function (type) {
        const area = document.getElementById('remAssignArea');
        if (type === 'department') {
            area.innerHTML = `<label><i class="fas fa-building"></i> Select Department</label><select id="remDept">${depts.map(d => `<option value="${escapeHtml(d)}">${escapeHtml(d)}</option>`).join('')}</select>`;
        } else if (type === 'custom') {
            area.innerHTML = `<label><i class="fas fa-users-cog"></i> Select Users</label><div id="customUsers" class="checkbox-grid">${users.map(u => `<label class="checkbox-chip"><input type="checkbox" value="${escapeHtml(u.userId)}"><span class="chip-label">${escapeHtml(u.displayName)}</span></label>`).join('')}</div>`;
        } else {
            area.innerHTML = `<label><i class="fas fa-user-check"></i> Select Person</label><select id="remPerson">${userOptions}</select>`;
        }
    };
}

async function saveReminder() {
    const title = document.getElementById('remTitle').value.trim();
    const desc = document.getElementById('remDesc').value.trim();
    const due = document.getElementById('remDue').value;
    const leadId = document.getElementById('remLead').value;
    const type = document.getElementById('remType').value;
    let assignedTo = [];
    let department = null;
    if (type === 'person') assignedTo = [document.getElementById('remPerson').value];
    else if (type === 'department') department = document.getElementById('remDept').value;
    else assignedTo = [...document.querySelectorAll('#customUsers input:checked')].map(cb => cb.value);
    const cc = [...document.querySelectorAll('#remCc input:checked')].map(cb => cb.value);
    if (!title) { toast('Title required', 'error'); return; }
    const reminderData = {
        title, desc, due,
        leadId: leadId || null,
        leadName: leadId ? (leads.find(l => l.id === leadId)?.name || '') : null,
        type, assignedTo, department, cc,
        createdBy: currentUser.userId,
        createdAt: Date.now(),
        id: null
    };
    if (firebaseEnabled) {
        const ref = await remindersRef.push(reminderData);
        await ref.update({ id: ref.key });
    } else {
        reminderData.id = `rem_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
        reminders.push(reminderData);
        persistLocalState();
    }
    closeModal();
    toast('Reminder created');
    if (currentPage === 'reminders') renderReminders();
}

