function renderLoanTypeDatalist(id = 'loanTypeList') {
    return `<datalist id="${id}">${loanTypes.map(type => `<option value="${type}"></option>`).join('')}</datalist>`;
}

function addLoanType() {
    const value = document.getElementById('newLoanType')?.value.trim();
    if (!value) { toast('Enter loan type name', 'error'); return; }
    if (loanTypes.includes(value)) { toast('Loan type already exists', 'error'); return; }
    const key = value.replace(/\s+/g, '_');
    if (firebaseEnabled) {
        loanTypesRef.child(key).set(value);
    }
    loanTypes.push(value);
    if (!firebaseEnabled) persistLocalState();
    const dataList = document.getElementById('loanTypeList');
    if (dataList) {
        dataList.innerHTML += `<option value="${value}"></option>`;
    }
    toast('Loan type added', 'success');
    document.getElementById('newLoanType').value = '';
}

function buildCcOptionsHtml(selectedIds = []) {
    return `
    <div class="cc-grid">
        ${users.map(u => {
            const isChecked = (selectedIds.includes(u.userId) || (selectedIds.length === 0 && u.userId === 'admin')) ? 'checked' : '';
            const initial = (u.displayName || u.userId || '?').charAt(0).toUpperCase();
            const roleLabel = u.role ? u.role.replace(/_/g, ' ').toUpperCase() : 'USER';
            return `
                <label class="cc-chip-card ${isChecked ? 'is-selected' : ''}">
                    <input type="checkbox" class="cc-monitor-cb" value="${u.userId}" ${isChecked} onchange="this.closest('.cc-chip-card').classList.toggle('is-selected', this.checked)">
                    <div class="cc-chip-inner">
                        <div class="cc-avatar-circle">${initial}</div>
                        <div class="cc-info">
                            <span class="cc-name">${escapeHtml(u.displayName || u.userId)}</span>
                            <span class="cc-role">${escapeHtml(roleLabel)}</span>
                        </div>
                    </div>
                </label>
            `;
        }).join('')}
    </div>
    `;
}

function openAddLead(leadId = null) {
    if (!leadId && !canUser('canCreateLeads')) {
        toast('Access Denied: You do not have permission to create leads.', 'error');
        return;
    }
    if (leadId && !canUser('canEditLeads')) {
        toast('Access Denied: You do not have permission to edit leads.', 'warning');
        return;
    }
    window.isAddLeadFormOpen = false;
    openAddEnquiry(leadId, true);
}
