function getThemeStorageKey(userId) {
    const id = userId || currentUser?.userId || 'guest';
    return `crm_user_theme_${id}`;
}

function getUserSavedTheme(userId) {
    const key = getThemeStorageKey(userId);
    const saved = localStorage.getItem(key);
    if (!saved) {
        return 'theme-gold';
    }
    return saved;
}

function applyUserTheme(themeId, userId = null, persist = true) {
    const validTheme = (themeId && AVAILABLE_THEMES.some(t => t.id === themeId)) ? themeId : 'theme-gold';
    document.documentElement.setAttribute('data-theme', validTheme);
    if (document.body) {
        document.body.setAttribute('data-theme', validTheme);
    }
    if (persist) {
        const key = getThemeStorageKey(userId);
        localStorage.setItem(key, validTheme);
        localStorage.setItem('crm_user_theme_guest', validTheme);
    }
}

function loadUserThemeOnLogin() {
    const savedTheme = getUserSavedTheme();
    applyUserTheme(savedTheme, null, false);
    try { applyBrandLogo(); } catch(e) {}
}

