function getVisibleToForLead(category, assignedTo) {
    const cat = (category || 'MSME').toLowerCase();
    const vis = [
        currentUser?.userId || 'admin',
        'admin',
        'admin_1',
        assignedTo
    ];
    if (cat.includes('msme') || cat.includes('sme')) {
        vis.push('anjali_jp');
        (users || []).filter(u => u.role === 'msme_head').forEach(u => vis.push(u.userId));
    }
    if (cat.includes('secured') && !cat.includes('unsecured')) {
        vis.push('aneena_s');
        (users || []).filter(u => u.role === 'retail_secured_head').forEach(u => vis.push(u.userId));
    }
    if (cat.includes('unsecured')) {
        vis.push('bilsy_j');
        (users || []).filter(u => u.role === 'retail_unsecured_head').forEach(u => vis.push(u.userId));
    }
    if (cat.includes('retail') && !cat.includes('secured') && !cat.includes('unsecured')) {
        vis.push('aneena_s', 'bilsy_j');
        (users || []).filter(u => u.role === 'retail_head' || u.role === 'retail_secured_head' || u.role === 'retail_unsecured_head').forEach(u => vis.push(u.userId));
    }
    return Array.from(new Set(vis.filter(Boolean)));
}

