async function restoreDataCenterItem(type, id) {
    const actorName = currentUser?.displayName || 'Admin';
    const nowIso = new Date().toISOString();
    const nowFormatted = safeFormatDateTime(Date.now());

    if (type === 'lead') {
        const l = (leads || []).find(x => x.id === id);
        if (l) {
            l.status = 'new';
            l.updatedAt = nowIso;
            l.updatedBy = currentUser?.id || 'admin';
            if (!Array.isArray(l.history)) l.history = [];
            l.history.push({
                action: 'Lead Restored from Data Centre',
                prevStatus: 'Data Centre',
                newStatus: 'New Leads',
                s: 'new',
                status: 'new',
                reason: 'Restored from Data Centre archive to active pipeline',
                remarks: 'Restored from Data Centre repository',
                nextStep: 'Active follow-up & processing',
                source: 'Data Centre',
                user: actorName,
                by: actorName,
                date: nowFormatted,
                time: nowIso,
                timestamp: Date.now(),
                icon: 'fa-undo-alt',
                iconColor: '#34d399'
            });

            if (typeof firebaseEnabled !== 'undefined' && firebaseEnabled && typeof leadsRef !== 'undefined' && leadsRef) {
                try { await leadsRef.child(l.id).set(l); } catch(e) {}
            }
            if (typeof saveLocalTableItem === 'function') {
                saveLocalTableItem('leads', l.id, l);
            }
            toast(`Lead restored to active status (${l.name})`, 'success');
        }
    } else {
        const e = (enquiries || []).find(x => x.id === id);
        if (e) {
            e.status = 'pending';
            e.updatedAt = nowIso;
            e.updatedBy = currentUser?.id || 'admin';
            if (!Array.isArray(e.history)) e.history = [];
            e.history.push({
                action: 'Enquiry Restored from Data Centre',
                prevStatus: 'Data Centre',
                newStatus: 'Pending Enquiry',
                s: 'pending',
                status: 'pending',
                reason: 'Restored from Data Centre archive to active enquiries',
                remarks: 'Restored from Data Centre repository',
                nextStep: 'Active enquiry follow-up',
                source: 'Data Centre',
                user: actorName,
                by: actorName,
                date: nowFormatted,
                time: nowIso,
                timestamp: Date.now(),
                icon: 'fa-undo-alt',
                iconColor: '#34d399'
            });

            if (typeof firebaseEnabled !== 'undefined' && firebaseEnabled && typeof enquiriesRef !== 'undefined' && enquiriesRef) {
                try { await enquiriesRef.child(e.id).set(e); } catch(e) {}
            }
            if (typeof saveLocalTableItem === 'function') {
                saveLocalTableItem('enquiries', e.id, e);
            }
            toast(`Enquiry restored to active pending state (${e.name})`, 'success');
        }
    }
    persistLocalState();
    if (typeof updateBadges === 'function') updateBadges();
    renderDataCenter();
}

async function dumpDataCenterItem(type, id) {
    if (typeof openRejectModal === 'function') {
        openRejectModal(type, id);
        return;
    }
    if (type === 'lead') {
        const l = (leads || []).find(x => x.id === id);
        if (l) {
            l.status = 'dump';
            if (typeof firebaseEnabled !== 'undefined' && firebaseEnabled && typeof leadsRef !== 'undefined' && leadsRef) {
                try { await leadsRef.child(l.id).set(l); } catch(e) {}
            }
            if (typeof saveLocalTableItem === 'function') {
                saveLocalTableItem('leads', l.id, l);
            }
        }
    } else {
        const e = (enquiries || []).find(x => x.id === id);
        if (e) {
            e.status = 'dumped';
            if (typeof firebaseEnabled !== 'undefined' && firebaseEnabled && typeof enquiriesRef !== 'undefined' && enquiriesRef) {
                try { await enquiriesRef.child(e.id).set(e); } catch(e) {}
            }
            if (typeof saveLocalTableItem === 'function') {
                saveLocalTableItem('enquiries', e.id, e);
            }
        }
    }
    persistLocalState();
    if (typeof updateBadges === 'function') updateBadges();
    toast('Item moved to Dump Store', 'info');
    renderDataCenter();
}

