    window.openManualUpdationModal = openManualUpdationModal;

    window.handleManualModalLeadSelect = function(leadId) {
        if (!leadId) return;
        const lead = (leads || []).find(l => l.id === leadId);
        if (!lead) return;
        const nameEl = document.getElementById('manualUpdationCaseName');
        const stageEl = document.getElementById('manualUpdationStage');
        const ownerEl = document.getElementById('manualUpdationOwner');
        const catEl = document.getElementById('manualUpdationCategory');
        if (nameEl) nameEl.value = lead.name || '';
        if (stageEl && lead.status) stageEl.value = lead.status;
        if (ownerEl) ownerEl.value = lead.assignedTo || currentUser?.displayName || 'Hasna';
        if (catEl) catEl.value = getDepartmentForLead(lead);
    };

    async function submitManualUpdationForm() {
        const dateVal = document.getElementById('manualUpdationDate')?.value;
        const owner = document.getElementById('manualUpdationOwner')?.value?.trim() || currentUser?.displayName || 'Hasna';
        const stage = document.getElementById('manualUpdationStage')?.value || 'In Discussion';
        const leadId = document.getElementById('manualUpdationLeadId')?.value;
        const manualName = document.getElementById('manualUpdationCaseName')?.value?.trim();
        const categoryVal = document.getElementById('manualUpdationCategory')?.value || 'MSME';
        const remarks = document.getElementById('manualUpdationRemarks')?.value?.trim();

        if (!remarks) {
            toast('Please enter remarks before saving.', 'warning');
            return;
        }

        const dObj = dateVal ? safeParseDate(dateVal) : new Date();
        const lead = (leads || []).find(l => l.id === leadId);
        const caseName = lead ? lead.name : (manualName || 'General Case');
        const finalCategory = lead ? getDepartmentForLead(lead) : categoryVal;

        const updateRecord = {
            id: 'dcu_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
            leadId: lead ? lead.id : ('manual_' + Date.now()),
            leadName: caseName,
            leadPhone: lead ? (lead.phone || '') : '',
            loanType: lead ? (lead.loanType || 'Loan') : (finalCategory === 'MSME' ? 'Working Capital' : (finalCategory === 'Retail - Secured' ? 'Home Loan' : 'Personal Loan')),
            category: finalCategory,
            checklistCategory: finalCategory,
            department: finalCategory,
            areaType: lead ? (lead.areaType || 'Urban') : 'Urban',
            status: stage,
            stage: stage,
            owner: owner,
            updatedBy: owner,
            userId: currentUser?.userId || 'user',
            updateType: 'manual_update',
            remarks: remarks,
            reviewStatus: 'Pending Review',
            reviewed: false,
            createdAt: dObj.toISOString(),
            dateStr: formatExcelDateStr(dObj)
        };

        if (lead) {
            if (!lead.dailyCases) lead.dailyCases = [];
            lead.dailyCases.unshift({
                id: updateRecord.id,
                date: updateRecord.createdAt,
                time: dObj.getTime(),
                by: owner,
                stage: stage,
                remarks: remarks,
                areaType: lead.areaType || 'Urban'
            });
            if (stage && stage !== lead.status) {
                const prevStage = lead.status;
                lead.status = stage;
                lead.stage = stage;
                if (!lead.history) lead.history = [];
                lead.history.unshift({
                    action: `Stage Changed: ${getStat(stage).l}`,
                    s: stage,
                    status: stage,
                    stage: stage,
                    by: owner,
                    d: formatExcelDateStr(dObj),
                    date: dObj.toISOString(),
                    reason: `Stage Changed: ${getStat(stage).l}`,
                    remarks: `Stage updated from ${getStat(prevStage).l} to ${getStat(stage).l}`
                });
            }
        }

        if (!window.dailyCaseUpdates) window.dailyCaseUpdates = [];
        window.dailyCaseUpdates.unshift(updateRecord);
        persistLocalState();

        try {
            if (leadsRef && lead) {
                await leadsRef.child(lead.id).update({
                    status: lead.status,
                    stage: lead.stage,
                    history: lead.history,
                    updatedAt: dObj.toISOString()
                });
            }
            if (leadsRef) {
                await firebase.database().ref('daily_case_updates').child(updateRecord.id).set(updateRecord);
            }
        } catch (e) {
            console.warn('Sync notice:', e);
        }

        toast('Manual update saved successfully!', 'success');
        closeModal();
        renderDailyCaseUpdates();
    }
