    function getLeadGenerateDate(l) {
        if (!l) return new Date();
        if (typeof l === 'string' || l instanceof Date || typeof l === 'number') {
            return safeParseDate(l);
        }

        let rawDate = l.leadGenerateDate || l.createdAt || l.created_at || l.created || l.date || l.leadDate;

        if (!rawDate && Array.isArray(l.history) && l.history.length > 0) {
            const createHist = l.history.find(h => h && (h.s === 'new' || h.status === 'new' || h.type === 'lead_created')) || l.history[0];
            if (createHist) {
                rawDate = parseHistoryTimestamp(createHist) || createHist.date || createHist.d || createHist.time;
            }
        }

        if (rawDate) {
            const parsed = safeParseDate(rawDate);
            if (parsed && !isNaN(parsed.getTime())) {
                return parsed;
            }
        }

        if (l.id) {
            const idStr = String(l.id);
            const match = idStr.match(/\d+/);
            const num = match ? (parseInt(match[0], 10) || 1) : 1;
            const fallback = new Date();
            fallback.setDate(fallback.getDate() - (((num * 7) % 45) + 2));
            return fallback;
        }

        return new Date();
    }

    function getExcelMonthName(val) {
        const d = (val && typeof val === 'object' && !(val instanceof Date)) ? getLeadGenerateDate(val) : safeParseDate(val);
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        return `-${months[d.getMonth()]}-`;
    }

    function getExcelDaysUpt(val) {
        const d = (val && typeof val === 'object' && !(val instanceof Date)) ? getLeadGenerateDate(val) : safeParseDate(val);
        const diff = Math.floor((new Date() - d) / (1000 * 60 * 60 * 24));
        return diff >= 0 ? diff : 0;
    }

    function getExcelStatusCode(status) {
        const s = (status || '').toLowerCase();
        if (s.includes('lead')) return 1;
        if (s.includes('database')) return 3;
        if (s.includes('doc')) return 4;
        if (s.includes('bank')) return 5;
        if (s.includes('follow')) return 8;
        if (s.includes('referred') || s.includes('retail')) return 11;
        return 1;
    }

    function formatExcelDateStr(val) {
        if (val === undefined || val === null || val === '') {
            return formatExcelDateStr(new Date());
        }
        const d = (val && typeof val === 'object' && !(val instanceof Date)) ? getLeadGenerateDate(val) : safeParseDate(val);
        return `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear()}`;
    }

    function formatExcelShortDate(val) {
        if (!val) return formatExcelDateStr(new Date());
        if (typeof val === 'string' && val.includes('/') && !val.includes(':') && val.length <= 10) return val;
        return formatExcelDateStr(val);
    }

