    function sanitizeDailyCaseUpdates() {
        if (!Array.isArray(window.dailyCaseUpdates)) return;
        const allLeads = Array.isArray(leads) ? leads : [];
        window.dailyCaseUpdates = window.dailyCaseUpdates.filter(u => {
            if (!u) return false;
            const rem = String(u.remarks || '').trim().toLowerCase();
            const act = String(u.action || '').trim().toLowerCase();
            if (rem.includes('lead details updated') ||
                rem.includes('transferred from enquiry') ||
                rem.includes('enquiry saved') ||
                rem.includes('lead registered') ||
                rem.includes('lead moved to') ||
                rem.includes('enquiry moved to') ||
                rem.includes('lead restored') ||
                rem.includes('follow-up scheduled') ||
                act.includes('details changed') ||
                act.includes('details updated')) {
                return false;
            }
            return true;
        });

        window.dailyCaseUpdates.forEach(u => {
            if (u.leadId && allLeads.length) {
                const matchedLead = allLeads.find(l => l.id === u.leadId);
                if (matchedLead) {
                    if (!u.leadName || u.leadName.startsWith('General Case') || u.leadName === 'Unnamed Lead') {
                        u.leadName = matchedLead.name;
                    }
                    if (!u.leadPhone) u.leadPhone = matchedLead.phone;
                    if (!u.loanType || u.loanType === 'Loan') u.loanType = matchedLead.loanType || 'Loan';
                    u.category = matchedLead.category || getDepartmentForLead(matchedLead);
                    u.department = getDepartmentForLead(matchedLead);
                    u.checklistCategory = u.department;
                }
            }
            if (!u.department || u.category === 'General' || !u.category) {
                if (u.loanType && u.loanType !== 'Loan') {
                    u.department = getDepartmentForLead(u);
                    u.category = u.department;
                    u.checklistCategory = u.department;
                } else if (u.remarks) {
                    const rem = u.remarks.toLowerCase();
                    if (rem.includes('home') || rem.includes('lap') || rem.includes('mortgage') || rem.includes('secured')) {
                        u.department = 'Retail - Secured';
                        u.category = 'Retail - Secured';
                        u.checklistCategory = 'Retail - Secured';
                        u.loanType = 'Home Loan';
                    } else if (rem.includes('personal') || rem.includes('car') || rem.includes('unsecured')) {
                        u.department = 'Retail - Unsecured';
                        u.category = 'Retail - Unsecured';
                        u.checklistCategory = 'Retail - Unsecured';
                        u.loanType = 'Personal Loan';
                    } else {
                        u.department = 'MSME';
                        u.category = 'MSME';
                        u.checklistCategory = 'MSME';
                        u.loanType = 'Working Capital';
                    }
                } else {
                    u.department = 'MSME';
                    u.category = 'MSME';
                    u.checklistCategory = 'MSME';
                    u.loanType = 'Working Capital';
                }
            }
        });
    }

