    async function saveInlineExcelDcu() {
        const dateVal = document.getElementById('excelInlineDate')?.value;
        const leadId = document.getElementById('excelInlineLeadId')?.value;
        const categoryVal = document.getElementById('excelInlineCategory')?.value || 'MSME';
        const stage = document.getElementById('excelInlineStage')?.value || 'In Discussion';
        const rawRemarks = document.getElementById('excelInlineRemarks')?.value?.trim();
        const owner = document.getElementById('excelInlineOwner')?.value?.trim() || currentUser?.displayName || 'Hasna';

        if (!rawRemarks) {
            toast('Please enter remarks added for the lead.', 'warning');
            return;
        }

        const dObj = dateVal ? safeParseDate(dateVal) : new Date();
        const dStr = `${dObj.getDate()}/${dObj.getMonth() + 1}/${dObj.getFullYear()}`;
        const remarks = /^\d{1,2}[\/\-\.]\d{1,2}[\/\-\.]\d{2,4}\s*[-:]\s*/.test(rawRemarks) ? rawRemarks : `${dStr}-${rawRemarks}`;

        const lead = (leads || []).find(l => l.id === leadId);
        const caseName = lead ? lead.name : 'General Case';
        const finalCategory = lead ? getDepartmentForLead(lead) : categoryVal;

        const updateRecord = {
            id: 'dcu_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
            leadId: lead ? lead.id : ('manual_' + Date.now()),
            leadName: caseName,
            leadPhone: lead ? (lead.phone || '') : '',
            loanType: lead ? (lead.loanType || 'Loan') : (finalCategory === 'MSME' ? 'Working Capital' : (finalCategory === 'Retail - Secured' ? 'Home Loan' : 'Personal Loan')),
            category: finalCategory,
            checklistCategory: finalCategory,
            department: finalCategory,
            areaType: lead ? (lead.areaType || 'Urban') : 'Urban',
            status: stage,
            stage: stage,
            owner: owner,
            updatedBy: owner,
            userId: currentUser?.userId || 'user',
            updateType: 'manual_update',
            remarks: remarks,
            reviewStatus: 'Pending Review',
            reviewed: false,
            createdAt: dObj.toISOString(),
            dateStr: formatExcelDateStr(dObj)
        };

        if (lead) {
            if (!lead.dailyCases) lead.dailyCases = [];
            lead.dailyCases.unshift({
                id: updateRecord.id,
                date: updateRecord.createdAt,
                time: dObj.getTime(),
                by: owner,
                stage: stage,
                remarks: remarks,
                areaType: lead.areaType || 'Urban'
            });
            if (stage && stage !== lead.status) {
                const prevStage = lead.status;
                lead.status = stage;
                lead.stage = stage;
                if (!lead.history) lead.history = [];
                lead.history.unshift({
                    action: `Stage Changed: ${getStat(stage).l}`,
                    s: stage,
                    status: stage,
                    stage: stage,
                    by: owner,
                    d: formatExcelDateStr(dObj),
                    date: dObj.toISOString(),
                    reason: `Stage Changed: ${getStat(stage).l}`,
                    remarks: `Stage updated from ${getStat(prevStage).l} to ${getStat(stage).l}`
                });
            }
        }

        if (!window.dailyCaseUpdates) window.dailyCaseUpdates = [];
        window.dailyCaseUpdates.unshift(updateRecord);
        persistLocalState();

        try {
            if (typeof leadsRef !== 'undefined' && leadsRef && lead) {
                await leadsRef.child(lead.id).update({
                    status: lead.status,
                    stage: lead.stage,
                    history: lead.history,
                    dailyCases: lead.dailyCases,
                    updatedAt: dObj.toISOString()
                });
            }
            if (typeof firebase !== 'undefined' && firebase.database) {
                await firebase.database().ref('daily_case_updates').child(updateRecord.id).set(updateRecord);
            }
        } catch (e) {
            console.warn('Sync notice:', e);
        }

        toast('Daily case update entry added successfully!', 'success');
        renderDailyCaseUpdates();
    };

    window.importDailyUpdatesFromExcelFile = function(fileInput) {
        const file = fileInput?.files?.[0];
        if (!file) return;

        if (typeof XLSX === 'undefined') {
            toast('Excel parser library loading... Please try again in a moment.', 'warning');
            return;
        }

        const activeDept = (window.activeDailyUpdateDept && window.activeDailyUpdateDept !== 'all')
            ? window.activeDailyUpdateDept 
            : (document.getElementById('dailyUpdateDeptFilter')?.value && document.getElementById('dailyUpdateDeptFilter')?.value !== 'all'
                ? document.getElementById('dailyUpdateDeptFilter')?.value
                : 'MSME');

        let targetDept = 'MSME';
        let defaultLoanType = 'Working Capital';
        if (activeDept === 'Retail - Secured') {
            targetDept = 'Retail - Secured';
            defaultLoanType = 'Home Loan';
        } else if (activeDept === 'Retail - Unsecured') {
            targetDept = 'Retail - Unsecured';
            defaultLoanType = 'Personal Loan';
        } else if (activeDept === 'Other Segment') {
            targetDept = 'Other Segment';
            defaultLoanType = 'Project Report / Loan';
        }

        const reader = new FileReader();
        reader.onload = function(e) {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];
                const jsonRows = XLSX.utils.sheet_to_json(worksheet, { defval: '' });

                if (!jsonRows || !jsonRows.length) {
                    toast('Uploaded Excel sheet is empty or contains no valid rows.', 'warning');
                    return;
                }

                let importedCount = 0;
                if (!window.dailyCaseUpdates) window.dailyCaseUpdates = [];

                jsonRows.forEach(row => {
                    let dateVal = row['DATE'] || row['Date'] || row['date'] || '';
                    let remarksVal = row['REMARKS'] || row['Remarks'] || row['remarks'] || row['COMMENT'] || row['Details'] || '';
                    let stageVal = row['STAGE'] || row['Stage'] || row['stage'] || row['Status'] || 'In Discussion';
                    let ownerVal = row['OWNER'] || row['Owner'] || row['owner'] || row['User'] || currentUser?.displayName || 'Hasna';

                    if (!remarksVal && !dateVal) return;

                    let dObj = new Date();
                    if (dateVal) {
                        if (typeof dateVal === 'number') {
                            dObj = new Date(Math.round((dateVal - 25569) * 86400 * 1000));
                        } else {
                            dObj = safeParseDate(String(dateVal));
                        }
                    }

                    const record = {
                        id: 'dcu_imp_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
                        leadId: 'manual_' + Date.now(),
                        leadName: `Imported Case (${targetDept})`,
                        leadPhone: '',
                        loanType: defaultLoanType,
                        category: targetDept,
                        checklistCategory: targetDept,
                        areaType: 'Urban',
                        status: String(stageVal).trim() || 'In Discussion',
                        stage: String(stageVal).trim() || 'In Discussion',
                        owner: String(ownerVal).trim() || 'Hasna',
                        updatedBy: String(ownerVal).trim() || 'Hasna',
                        userId: currentUser?.userId || 'user',
                        department: targetDept,
                        updateType: 'excel_import',
                        remarks: String(remarksVal).trim() || 'No remarks provided',
                        reviewStatus: 'Pending Review',
                        reviewed: false,
                        createdAt: dObj.toISOString(),
                        dateStr: formatExcelDateStr(dObj)
                    };

                    window.dailyCaseUpdates.unshift(record);
                    importedCount++;

                    try {
                        if (typeof leadsRef !== 'undefined' && leadsRef) {
                            firebase.database().ref('daily_case_updates').child(record.id).set(record);
                        }
                    } catch (err) {
                        console.warn('Firebase batch sync notice:', err);
                    }
                });

                persistLocalState();
                toast(`Successfully imported ${importedCount} updates into ${targetDept} spreadsheet!`, 'success');
                renderDailyCaseUpdates();
                if (fileInput) fileInput.value = '';
            } catch (err) {
                console.error('Import error:', err);
                toast('Error reading Excel file: ' + err.message, 'error');
            }
        };
        reader.readAsArrayBuffer(file);
    };

