    function exportFullExcelModelWorkbook(deptParam) {
        if (!canUser('canExportData')) {
            toast('Access Denied: You do not have permission to export data.', 'error');
            return;
        }
        if (typeof XLSX === 'undefined') {
            toast('Excel library loading... Please try again in a moment.', 'warning');
            return;
        }

        // Determine department filter
        let dept = deptParam;
        if (!dept) {
            const uiDept = document.getElementById('dailyUpdateDeptFilter')?.value;
            dept = (uiDept && uiDept !== 'all') ? uiDept : 'all';
        }

        let targetLeads = Array.isArray(leads) ? leads : [];
        if (dept && dept !== 'all' && dept !== 'All') {
            targetLeads = targetLeads.filter(l => matchesDepartmentFilter(l, dept));
        }

        // Department display label & filename suffix
        let deptLabel = 'All Departments';
        let fileDeptSuffix = 'All_Departments';
        if (dept === 'MSME' || dept === 'msme') {
            deptLabel = 'Business (MSME)';
            fileDeptSuffix = 'MSME';
        } else if (dept === 'Retail - Secured' || dept === 'retail_secured') {
            deptLabel = 'Retail - Secured';
            fileDeptSuffix = 'Retail_Secured';
        } else if (dept === 'Retail - Unsecured' || dept === 'retail_unsecured') {
            deptLabel = 'Retail - Unsecured';
            fileDeptSuffix = 'Retail_Unsecured';
        } else if (dept === 'Other Segment' || dept === 'other') {
            deptLabel = 'Other Segment';
            fileDeptSuffix = 'Other_Segment';
        }

        const wb = XLSX.utils.book_new();

        // 1. LEADS
        const leadsData = targetLeads.map(l => {
            const leadGenDate = getLeadGenerateDate(l);
            return {
                'DAYS UPT': getExcelDaysUpt(leadGenDate),
                'LEAD GENERATE DATE': formatExcelDateStr(leadGenDate),
                'MONTH': getExcelMonthName(leadGenDate),
                'NAME': l.name || '',
                'STATUS': l.status || 'Leads',
                'STATUS CODE': getExcelStatusCode(l.status),
                'PH. NO': l.phone || '',
                'AMOUNT (IN LAKHS)': l.amount || 0,
                'SOURCE': l.source || '',
                'OWNER': l.assignedTo || l.createdBy || '',
                'REFERRAL': l.referral || l.referredBy || '',
                'PRODUCT': l.loanType || '',
                'LAST UPDATE DATE': formatExcelDateStr(l.updatedAt || leadGenDate),
                'REMARKS': l.remarks || ''
            };
        });
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(leadsData.length ? leadsData : [{ 'NAME': `No Leads in ${deptLabel}` }]), 'LEADS');

        // 2. CURRENT FOLLOWUP
        const cfData = targetLeads.filter(l => ['new', 'followup', 'immediate', 'probable', 'next', 'documentation', 'bank_finalisation', 'current_followup'].includes(l.status)).map(l => {
            const leadGenDate = getLeadGenerateDate(l);
            return {
                'MO': getExcelMonthName(leadGenDate),
                'NAME': l.name || '',
                'STATUS': (l.status || '').toUpperCase(),
                'STAGE': (l.stage || l.status || '').toUpperCase(),
                'PH NO': l.phone || '',
                'AM': l.amount || 0,
                'BANK': l.bankName || l.bank || '',
                'DATE': formatExcelDateStr(l.updatedAt || leadGenDate),
                'REMARK': l.remarks || '',
                'SOU': l.source || '',
                'OWNER': l.assignedTo || l.createdBy || '',
                'REFFERE': l.referral || l.referredBy || '',
                'PRODUCT': l.loanType || ''
            };
        });
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(cfData.length ? cfData : [{ 'NAME': `No Current Followup in ${deptLabel}` }]), 'CURRENT FOLLOWUP');

        // 3. DISBURSED
        const disbData = targetLeads.filter(l => ['disbursed', 'closed', 'sanctioned'].includes(l.status)).map(l => {
            const leadGenDate = getLeadGenerateDate(l);
            return {
                'NAME': l.name || '',
                'PHONE': l.phone || '',
                'CONTACT': l.contactPerson || '',
                'BANK': l.bankName || l.bank || '',
                'AMOU': l.amount || 0,
                'PRODUCT': l.loanType || '',
                'DISBURS': formatExcelDateStr(l.disbursedDate || l.updatedAt),
                'LEAD DATE': formatExcelDateStr(leadGenDate),
                'FEE %': l.feePercent ? `${l.feePercent}%` : '1.25%',
                'TOTAL': l.totalFee || 0,
                'GST': l.gst || 0,
                'TDS': l.tds || 0,
                'PAYOUT RECEIVED DATE': formatExcelDateStr(l.payoutDate || l.updatedAt),
                'WITH OR': l.withGst ? 'with gst' : 'without gst'
            };
        });
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(disbData.length ? disbData : [{ 'NAME': `No Disbursed in ${deptLabel}` }]), 'DISBURSED');

        // 4. Bank Payout and Inter dept Payout
        const rawBpList = (typeof bankPayouts !== 'undefined' && Array.isArray(bankPayouts)) ? bankPayouts : [];
        let bpList = rawBpList.length ? rawBpList : targetLeads.filter(l => ['disbursed', 'closed', 'sanctioned'].includes(l.status)).map(l => ({
            leadId: l.id,
            leadName: l.name,
            disbursedAmount: l.amount ? `${l.amount} Lakhs` : '0',
            payoutAmount: l.totalFee || (l.amount ? Math.round(l.amount * 100000 * 0.0125) : 0),
            tds: l.tds || 0,
            gst: l.gst || 0,
            actualPayout: (l.totalFee || (l.amount ? Math.round(l.amount * 100000 * 0.0125) : 0)) - (l.tds || 0),
            receivedDate: l.payoutDate || l.updatedAt || getLeadGenerateDate(l)
        }));
        if (dept && dept !== 'all' && dept !== 'All' && rawBpList.length) {
            bpList = bpList.filter(b => {
                const matchedLead = targetLeads.find(l => l.id === b.leadId || l.name === b.leadName);
                return !!matchedLead;
            });
        }
        const bpData = bpList.map(b => ({
            'NAME': b.leadName || b.name || '',
            'DISBURSED': b.disbursedAmount || 0,
            'BANK PAYOUT': b.payoutAmount || 0,
            'TDS': b.tds || 0,
            'GST': b.gst || 0,
            'ACTUAL': b.actualPayout || 0,
            'PAYOUT RECEIVED DATE': formatExcelDateStr(b.receivedDate || new Date())
        }));
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(bpData.length ? bpData : [{ 'NAME': `No Bank Payouts in ${deptLabel}` }]), 'Bank Payout and Inter dept');

        // 5. FOLLOWUP
        const fData = targetLeads.filter(l => l.status === 'followup').map(l => {
            const leadGenDate = getLeadGenerateDate(l);
            return {
                'DATE': formatExcelDateStr(l.updatedAt),
                'NAME': l.name || '',
                'PH. NO': l.phone || '',
                'AMOUNT': l.amount || 0,
                'REFERENCE': l.referral || l.referredBy || '',
                'PRODUCT': l.loanType || '',
                'LAST DATE': formatExcelDateStr(l.updatedAt),
                'STATUS': l.status || '',
                'BANK NAME': l.bankName || '',
                'LEAD DATE': formatExcelDateStr(leadGenDate)
            };
        });
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(fData.length ? fData : [{ 'NAME': `No Followup in ${deptLabel}` }]), 'FOLLOWUP');

        // 6. DATABASE
        const dbData = targetLeads.filter(l => l.status === 'database').map(l => {
            const leadGenDate = getLeadGenerateDate(l);
            return {
                'FILE NAME': l.name || '',
                'PHONE NUMBER': l.phone || '',
                'AMOUNT': l.amount || 0,
                'PRODUCT': l.loanType || '',
                'REMARKS': l.remarks || '',
                'SOURCE': l.source || '',
                'REFERENCE': l.referral || l.referredBy || '',
                'LEAD DATE': formatExcelDateStr(leadGenDate),
                'BANK NAME': l.bankName || '',
                'DATABASE DATE': formatExcelDateStr(l.updatedAt)
            };
        });
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(dbData.length ? dbData : [{ 'FILE NAME': `No Database in ${deptLabel}` }]), 'DATABASE');

        // 7. DUMB
        const dumbData = targetLeads.filter(l => ['dump', 'rejected', 'dumb', 'hold'].includes(l.status)).map(l => {
            const leadGenDate = getLeadGenerateDate(l);
            return {
                'LEAD GENERATE DATE': formatExcelDateStr(leadGenDate),
                'NAME': l.name || '',
                'PH. NO': l.phone || '',
                'AMOUNT': l.amount || 0,
                'SOURCE': l.source || '',
                'REFERRAL': l.referral || l.referredBy || '',
                'PRODUCT': l.loanType || '',
                'LAST': formatExcelDateStr(l.updatedAt),
                'REMARKS': l.remarks || ''
            };
        });
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(dumbData.length ? dumbData : [{ 'NAME': `No Dump in ${deptLabel}` }]), 'DUMB');

        // 8. Project report
        const prData = targetLeads.filter(l => (l.category === 'MSME' || (l.loanType || '').toLowerCase().includes('project'))).map(l => {
            const leadGenDate = getLeadGenerateDate(l);
            return {
                'LEAD GENERATE DATE': formatExcelDateStr(leadGenDate),
                'MONTH': getExcelMonthName(leadGenDate),
                'NAME': l.name || '',
                'AMT': l.amount || 0,
                'PH. NO': l.phone || '',
                'OWNER': l.assignedTo || l.createdBy || '',
                'PRODUCT': l.loanType || '',
                'REFERRAL': l.referral || l.referredBy || '',
                'REMARKS': l.remarks || '',
                'COMPLETED DATE': formatExcelDateStr(l.completedDate || l.updatedAt)
            };
        });
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(prData.length ? prData : [{ 'NAME': `No Project Reports in ${deptLabel}` }]), 'Project report');

        // 9. retail interdepartment
        const riData = targetLeads.filter(l => l.referredToRetail || (l.department === 'retail' && l.source === 'referral')).map(l => ({
            'NAME': l.name || '',
            'PRODUCT': l.loanType || '',
            'AMOUNT': l.amount || 0,
            'WORKS DONE': l.remarks || ''
        }));
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(riData.length ? riData : [{ 'NAME': `No Retail Interdepartment in ${deptLabel}` }]), 'retail interdepartment');

        // 10. R2R
        const r2rData = targetLeads.filter(l => l.referredToRetail || l.status === 'referred_to_retail').map((l, i) => ({
            'SL.NO': i + 1,
            'NAME': l.name || '',
            'PH.NO': l.phone || '',
            'AMOUNT': l.amount || 0,
            'SOURCE': l.source || '',
            'REFFERED BY': l.referral || l.referredBy || '',
            'PRODUCT': l.loanType || '',
            'REASON': l.remarks || ''
        }));
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(r2rData.length ? r2rData : [{ 'NAME': `No R2R in ${deptLabel}` }]), 'R2R');

        // 11. INDEX
        const indexRows = [
            ['STATUS INDEX', '', ''],
            [1, 'IMMEDIATE', 'to be actively followed up this month itself for bank finalisation/login/sanction/ disbursement'],
            [2, 'PROBABLE', 'lead which hasnt been confirmed either by bank or by customer but there is chances of conversion to current/next/follow up.lead within first 15 days to be included.'],
            [3, 'NEXT', 'confirmed for a later date with docs/part disb/sanction but not this month disbursement'],
            [4, 'FOLLOW UP', 'active cases needs to be followed up in every 7 days/ as per customer request (weekly once calling)'],
            [5, 'DATABASE', 'potential customer but not possible now/not responding/ not interested now/rejected cases but done in some other bank thru other channels'],
            [6, 'DUMP', 'passive database for loans. no follow up required'],
            ['', '', ''],
            ['LEADS INDEX', '', ''],
            [1, 'Leads', 'As and when lead is generated, it should reflect here'],
            [2, 'Probable', 'Not enough info recd even after call made'],
            [3, 'Hot Leads', 'Immediate followup cases which needs to be transferred to current follow up sheet'],
            [4, 'Documentation', 'Cases wherein some documents are still pending for receipt'],
            [5, 'Bank Finallisation', 'Cases ready for Bank finalisation'],
            [6, 'Current followup', 'needs to be followed up and hence cases alredy move to current followup sheet'],
            [7, 'Special Follow up', ''],
            [8, 'follow up', 'active cases needs to be followed up in every 7 days/ as per customer request (weekly once calling)'],
            [9, 'Database', 'potential customer but not possible now/not responding/not interested now/rejected cases but done in some other bank thru other channels, these cases should move to database sheet'],
            [10, 'Dumb', 'passive database for loans. no follow up required should move to dump sheet'],
            [11, 'Referred to retail', 'The leads generated in the SME department have been transferred to the retail department.'],
            ['', '', ''],
            ['', '', ''],
            ['STAGE INDEX', '', ''],
            [1, 'DISBURSED', 'already disbursed with date of disbursement to be noted'],
            [2, 'TO DISB', 'all formalities completed and ready to disburse files'],
            [3, 'TO SANCTION', 'login pendings cleared,legal and tech formalities completed and awaiting sanction'],
            [4, 'TO LOGIN', 'all documents and info received.Either physical file submitted to bank/online login awaited'],
            [5, 'TO FINALIZE', 'all relevant documents and info collected, but bank not finalised'],
            [6, 'HOT LEADS', 'needs rigourous follow up to move this to login stage']
        ];

        const indexSheet = XLSX.utils.aoa_to_sheet(indexRows);
        indexSheet['!merges'] = [
            { s: { r: 0, c: 0 }, e: { r: 0, c: 2 } },
            { s: { r: 8, c: 0 }, e: { r: 8, c: 2 } },
            { s: { r: 22, c: 0 }, e: { r: 22, c: 2 } }
        ];
        indexSheet['!cols'] = [
            { wch: 8 },
            { wch: 25 },
            { wch: 110 }
        ];

        // Apply Excel blue header styles & borders
        const blueHeaderStyle = {
            fill: { fgColor: { rgb: "1F497D" } }, // Dark blue header fill
            font: { name: "Calibri", sz: 12, bold: true, color: { rgb: "FFFFFF" } },
            alignment: { horizontal: "center", vertical: "center" },
            border: {
                top: { style: "thin", color: { rgb: "000000" } },
                bottom: { style: "thin", color: { rgb: "000000" } },
                left: { style: "thin", color: { rgb: "000000" } },
                right: { style: "thin", color: { rgb: "000000" } }
            }
        };

        const cellBorderStyle = {
            top: { style: "thin", color: { rgb: "000000" } },
            bottom: { style: "thin", color: { rgb: "000000" } },
            left: { style: "thin", color: { rgb: "000000" } },
            right: { style: "thin", color: { rgb: "000000" } }
        };

        const headerRowIndices = [0, 8, 22]; // STATUS INDEX (r=0), LEADS INDEX (r=8), STAGE INDEX (r=22)

        Object.keys(indexSheet).forEach(cellRef => {
            if (cellRef.startsWith('!')) return;
            const decoded = XLSX.utils.decode_cell(cellRef);
            if (headerRowIndices.includes(decoded.r)) {
                indexSheet[cellRef].s = blueHeaderStyle;
            } else {
                if (indexSheet[cellRef] && indexSheet[cellRef].v !== undefined && indexSheet[cellRef].v !== '') {
                    indexSheet[cellRef].s = {
                        font: { name: "Calibri", sz: 11 },
                        alignment: { vertical: "center", wrapText: true, horizontal: decoded.c === 0 ? "center" : "left" },
                        border: cellBorderStyle
                    };
                }
            }
        });

        // Ensure merged cells across columns A, B, C for header rows receive the blue fill style
        ['A1', 'B1', 'C1', 'A9', 'B9', 'C9', 'A23', 'B23', 'C23'].forEach(ref => {
            if (!indexSheet[ref]) {
                indexSheet[ref] = { t: 's', v: '' };
            }
            indexSheet[ref].s = blueHeaderStyle;
        });

        XLSX.utils.book_append_sheet(wb, indexSheet, 'INDEX');

        // Apply Excel header styles & borders to all standard data sheets
        wb.SheetNames.forEach(sheetName => {
            const ws = wb.Sheets[sheetName];
            if (sheetName === 'INDEX' || !ws || !ws['!ref']) return;

            const range = XLSX.utils.decode_range(ws['!ref']);
            const colWidths = [];

            const yellowHeaderStyle = {
                fill: { fgColor: { rgb: "FFFF00" } }, // Bright Yellow header fill matching user screenshot
                font: { name: "Calibri", sz: 11, bold: true, color: { rgb: "000000" } },
                alignment: { horizontal: "center", vertical: "center", wrapText: true },
                border: {
                    top: { style: "thin", color: { rgb: "000000" } },
                    bottom: { style: "medium", color: { rgb: "000000" } },
                    left: { style: "thin", color: { rgb: "000000" } },
                    right: { style: "thin", color: { rgb: "000000" } }
                }
            };

            const headerStyle = {
                fill: { fgColor: { rgb: "1F497D" } }, // Professional Dark Navy Blue header fill
                font: { name: "Calibri", sz: 11, bold: true, color: { rgb: "FFFFFF" } },
                alignment: { horizontal: "center", vertical: "center", wrapText: true },
                border: {
                    top: { style: "thin", color: { rgb: "000000" } },
                    bottom: { style: "medium", color: { rgb: "000000" } },
                    left: { style: "thin", color: { rgb: "000000" } },
                    right: { style: "thin", color: { rgb: "000000" } }
                }
            };

            const cellBorder = {
                top: { style: "thin", color: { rgb: "D1D5DB" } },
                bottom: { style: "thin", color: { rgb: "D1D5DB" } },
                left: { style: "thin", color: { rgb: "D1D5DB" } },
                right: { style: "thin", color: { rgb: "D1D5DB" } }
            };

            for (let R = range.s.r; R <= range.e.r; ++R) {
                for (let C = range.s.c; C <= range.e.c; ++C) {
                    const cellRef = XLSX.utils.encode_cell({ r: R, c: C });
                    if (!ws[cellRef]) continue;

                    const valStr = String(ws[cellRef].v ?? '');
                    colWidths[C] = Math.max(colWidths[C] || 10, valStr.length + 4);

                    if (R === 0) {
                        // Header cell
                        ws[cellRef].s = (sheetName === 'DAILY CASE UPDATES' || sheetName.includes('DAILY')) ? yellowHeaderStyle : headerStyle;
                    } else {
                        // Data cell
                        ws[cellRef].s = {
                            font: { name: "Calibri", sz: 10 },
                            alignment: {
                                vertical: "center",
                                horizontal: (typeof ws[cellRef].v === 'number') ? "right" : "left"
                            },
                            border: cellBorder
                        };
                    }
                }
            }

            ws['!cols'] = colWidths.map(w => ({ wch: Math.min(Math.max(w, 12), 50) }));
            ws['!rows'] = [{ hpt: 26 }]; // Distinct header height
        });

        XLSX.writeFile(wb, `Profit_Center_Master_Model_${fileDeptSuffix}_${new Date().toISOString().slice(0, 10)}.xlsx`);
        toast(`Exported Profit Center (${deptLabel}) Master Model (.xlsx) successfully!`, 'success');
    }
    window.exportFullExcelModelWorkbook = exportFullExcelModelWorkbook;

    window.exportDailyCaseUpdatesOnlyExcel = function(deptParam) {
        if (!canUser('canExportData')) {
            toast('Access Denied: You do not have permission to export data.', 'error');
            return;
        }
        const dept = deptParam || document.getElementById('dailyUpdateDeptFilter')?.value || 'all';
        let exportLogs = [];
        if (Array.isArray(window.dailyCaseUpdates)) {
            exportLogs = [...window.dailyCaseUpdates];
        }
        (leads || []).forEach(l => {
            if (Array.isArray(l.history)) {
                l.history.forEach((h, idx) => {
                    const logTime = safeParseDate(h.date || h.d);
                    const logId = 'lead_hist_' + l.id + '_' + idx;
                    if (!exportLogs.some(existing => existing.id === logId || (existing.leadId === l.id && existing.createdAt === logTime.toISOString() && existing.remarks === h.remarks))) {
                        exportLogs.push({
                            id: logId,
                            leadId: l.id,
                            leadName: l.name,
                            leadPhone: l.phone,
                            loanType: l.loanType,
                            category: l.category,
                            status: h.status || h.s || l.status,
                            stage: h.stage || h.status || h.s || l.stage || l.status,
                            owner: h.owner || h.by || l.assignedTo || l.createdBy || 'Hasna',
                            updatedBy: h.by || getUserDisplayName(h.userId) || 'User',
                            userId: h.userId || l.createdBy,
                            department: h.department || l.checklistCategory || getDepartmentForLead(l),
                            updateType: h.type === 'manual_daily_update' ? 'manual_update' : (h.s === 'new' ? 'lead_created' : 'status_change'),
                            remarks: h.remarks || `Status changed to ${h.status || h.s}`,
                            createdAt: logTime.toISOString(),
                            dateStr: h.d || formatExcelDateStr(logTime)
                        });
                    }
                });
            }
        });

        if (dept && dept !== 'all' && dept !== 'All') {
            exportLogs = exportLogs.filter(item => matchesDepartmentFilter(item, dept));
        }

        // Group by lead so each lead has one row with full date-prefixed remarks matching the user request
        const exportGroupedMap = new Map();
        exportLogs.forEach(item => {
            const key = (item.leadId && !item.leadId.startsWith('manual_')) 
                ? ('lead_' + item.leadId) 
                : (item.leadName ? ('name_' + item.leadName.trim().toLowerCase()) : ('item_' + item.id));
            
            const itemDate = safeParseDate(item.createdAt || item.dateStr);

            if (!exportGroupedMap.has(key)) {
                exportGroupedMap.set(key, {
                    latestDate: itemDate,
                    leadName: item.leadName || 'General Case',
                    leadPhone: item.leadPhone || '',
                    category: item.category || item.department || 'MSME',
                    stage: item.stage || item.status || '',
                    owner: item.owner || item.updatedBy || 'Hasna',
                    remarksList: []
                });
            }

            const g = exportGroupedMap.get(key);
            if (itemDate > g.latestDate) {
                g.latestDate = itemDate;
                if (item.stage) g.stage = item.stage;
                if (item.owner) g.owner = item.owner;
            }

            const remText = String(item.remarks || '').trim();
            if (remText) {
                g.remarksList.push({
                    remarks: remText,
                    date: itemDate
                });
            }
        });

        const sheetData = Array.from(exportGroupedMap.values())
            .sort((a, b) => b.latestDate - a.latestDate)
            .map(g => {
                g.remarksList.sort((a, b) => b.date - a.date);
                const seen = new Set();
                const combined = g.remarksList.map(rem => {
                    const rDate = safeParseDate(rem.date);
                    const dStr = !isNaN(rDate.getTime()) ? `${rDate.getDate()}/${rDate.getMonth() + 1}/${rDate.getFullYear()}` : formatExcelShortDate(new Date());
                    let raw = String(rem.remarks || '').trim();
                    const dateMatch = raw.match(/^(\d{1,2}[\/\-\.]\d{1,2}[\/\-\.]\d{2,4})\s*[-:]\s*(.*)$/s);
                    const prefix = dateMatch ? dateMatch[1] : dStr;
                    const body = dateMatch ? dateMatch[2] : raw;
                    const key = prefix + '-' + body.toLowerCase();
                    if (seen.has(key)) return null;
                    seen.add(key);
                    return `${prefix}-${body}`;
                }).filter(Boolean).join(', ');

                const latestD = safeParseDate(g.latestDate);
                const latestDStr = !isNaN(latestD.getTime()) ? `${latestD.getDate()}/${latestD.getMonth() + 1}/${latestD.getFullYear()}` : formatExcelShortDate(g.latestDate);

                return {
                    'DATE': latestDStr,
                    'LEAD NAME': g.leadName,
                    'PHONE': g.leadPhone,
                    'CATEGORY': g.category,
                    'STAGE': g.stage,
                    'REMARKS': combined || '-',
                    'OWNER': g.owner
                };
            });

        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.json_to_sheet(sheetData.length ? sheetData : [{
            'DATE': formatExcelDateStr(new Date()),
            'LEAD NAME': '',
            'PHONE': '',
            'CATEGORY': '',
            'STAGE': '',
            'REMARKS': 'No case updates found',
            'OWNER': ''
        }]);

        ws['!cols'] = [
            { wch: 15 }, // DATE
            { wch: 25 }, // LEAD NAME
            { wch: 16 }, // PHONE
            { wch: 18 }, // CATEGORY
            { wch: 18 }, // STAGE
            { wch: 75 }, // REMARKS
            { wch: 18 }  // OWNER
        ];

        const range = XLSX.utils.decode_range(ws['!ref']);
        const yellowHeaderStyle = {
            fill: { fgColor: { rgb: "FFFF00" } },
            font: { name: "Calibri", sz: 11, bold: true, color: { rgb: "000000" } },
            alignment: { horizontal: "center", vertical: "center", wrapText: true },
            border: {
                top: { style: "thin", color: { rgb: "000000" } },
                bottom: { style: "medium", color: { rgb: "000000" } },
                left: { style: "thin", color: { rgb: "000000" } },
                right: { style: "thin", color: { rgb: "000000" } }
            }
        };

        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellRef = XLSX.utils.encode_cell({ r: 0, c: C });
            if (ws[cellRef]) ws[cellRef].s = yellowHeaderStyle;
        }

        const dataCellBorder = {
            top: { style: "thin", color: { rgb: "000000" } },
            bottom: { style: "thin", color: { rgb: "000000" } },
            left: { style: "thin", color: { rgb: "000000" } },
            right: { style: "thin", color: { rgb: "000000" } }
        };

        for (let R = range.s.r + 1; R <= range.e.r; ++R) {
            for (let C = range.s.c; C <= range.e.c; ++C) {
                const cellRef = XLSX.utils.encode_cell({ r: R, c: C });
                if (ws[cellRef]) {
                    ws[cellRef].s = {
                        font: { name: "Calibri", sz: 11 },
                        alignment: {
                            vertical: "center",
                            horizontal: (C === 0 || C === 2 || C === 3) ? "center" : "left",
                            wrapText: true
                        },
                        border: dataCellBorder
                    };
                }
            }
        }

        ws['!rows'] = [{ hpt: 26 }];

        XLSX.utils.book_append_sheet(wb, ws, 'CASE UPDATES');
        XLSX.writeFile(wb, `CASE_UPDATES_${dept}_${new Date().toISOString().slice(0, 10)}.xlsx`);
        toast('Case Updates Excel file generated successfully!', 'success');
    };

    window.handleSinglePageLeadSelect = function(leadId) {
        if (!leadId) return;
        const lead = (leads || []).find(l => l.id === leadId);
        if (!lead) return;
        
        const manualNameEl = document.getElementById('singlePageDcuManualName');
        const stageEl = document.getElementById('singlePageDcuStage');
        const ownerEl = document.getElementById('singlePageDcuOwner');

        if (manualNameEl) manualNameEl.value = lead.name || '';
        if (stageEl && lead.status) stageEl.value = lead.status;
        if (ownerEl) ownerEl.value = lead.assignedTo || currentUser?.displayName || 'Hasna';
    };

    window.saveSinglePageManualDcu = async function() {
        const dateVal = document.getElementById('singlePageDcuDate')?.value;
        const leadId = document.getElementById('singlePageDcuLeadId')?.value;
        const manualName = document.getElementById('singlePageDcuManualName')?.value?.trim();
        const rawRemarks = document.getElementById('singlePageDcuRemarks')?.value?.trim();
        const stage = document.getElementById('singlePageDcuStage')?.value || 'In Discussion';
        const owner = document.getElementById('singlePageDcuOwner')?.value?.trim() || currentUser?.displayName || 'Hasna';

        if (!rawRemarks) {
            toast('Please enter a case update note before saving.', 'warning');
            return;
        }

        const dObj = dateVal ? safeParseDate(dateVal) : new Date();
        const dStr = `${dObj.getDate()}/${dObj.getMonth() + 1}/${dObj.getFullYear()}`;
        const remarks = /^\d{1,2}[\/\-\.]\d{1,2}[\/\-\.]\d{2,4}\s*[-:]\s*/.test(rawRemarks) ? rawRemarks : `${dStr}-${rawRemarks}`;

        const lead = (leads || []).find(l => l.id === leadId);
        const caseName = lead ? lead.name : (manualName || 'General Case');
        const casePhone = lead ? lead.phone : '';
        const loanType = lead ? lead.loanType : 'Loan';

        const updateRecord = {
            id: 'dcu_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
            leadId: lead ? lead.id : ('manual_' + Date.now()),
            leadName: caseName,
            leadPhone: casePhone,
            loanType: loanType,
            category: lead ? lead.category : 'General',
            areaType: lead ? lead.areaType : 'Urban',
            status: stage,
            stage: stage,
            owner: owner,
            updatedBy: owner,
            userId: currentUser?.userId || 'user',
            department: currentUser?.department || 'MSME',
            updateType: 'manual_update',
            remarks: remarks,
            reviewStatus: 'Pending Review',
            reviewed: false,
            createdAt: dObj.toISOString(),
            dateStr: formatExcelDateStr(dObj)
        };

        if (lead) {
            if (!lead.dailyCases) lead.dailyCases = [];
            lead.dailyCases.unshift({
                id: updateRecord.id,
                date: updateRecord.createdAt,
                time: dObj.getTime(),
                by: owner,
                stage: stage,
                remarks: remarks,
                areaType: lead.areaType || 'Urban'
            });
            if (stage && stage !== lead.status) {
                const prevStage = lead.status;
                lead.status = stage;
                lead.stage = stage;
                if (!lead.history) lead.history = [];
                lead.history.unshift({
                    action: `Stage Changed: ${getStat(stage).l}`,
                    s: stage,
                    status: stage,
                    stage: stage,
                    by: owner,
                    d: formatExcelDateStr(dObj),
                    date: dObj.toISOString(),
                    reason: `Stage Changed: ${getStat(stage).l}`,
                    remarks: `Stage updated from ${getStat(prevStage).l} to ${getStat(stage).l}`
                });
            }
        }

        if (!window.dailyCaseUpdates) window.dailyCaseUpdates = [];
        window.dailyCaseUpdates.unshift(updateRecord);
        persistLocalState();

        try {
            if (leadsRef && lead) {
                await leadsRef.child(lead.id).update({
                    status: lead.status,
                    stage: lead.stage,
                    history: lead.history,
                    updatedAt: dObj.toISOString()
                });
            }
            if (leadsRef) {
                await firebase.database().ref('daily_case_updates').child(updateRecord.id).set(updateRecord);
            }
        } catch (e) {
            console.warn('Sync notice:', e);
        }

        toast('Case update entry added successfully!', 'success');
        if (document.getElementById('singlePageDcuRemarks')) document.getElementById('singlePageDcuRemarks').value = '';
        if (document.getElementById('singlePageDcuManualName')) document.getElementById('singlePageDcuManualName').value = '';

        renderDailyCaseUpdates();
    };

    window.deleteDailyCaseUpdate = function(id) {
        if (!confirm('Are you sure you want to delete this case update entry?')) return;
        if (Array.isArray(window.dailyCaseUpdates)) {
            window.dailyCaseUpdates = window.dailyCaseUpdates.filter(i => i.id !== id);
        }
        if (Array.isArray(leads)) {
            leads.forEach(l => {
                if (Array.isArray(l.dailyCases)) {
                    l.dailyCases = l.dailyCases.filter(dc => dc.id !== id && ('dcu_' + l.id + '_' + (dc.time || 0)) !== id);
                }
            });
        }
        persistLocalState();
        try {
            if (typeof firebase !== 'undefined' && firebase.database) {
                firebase.database().ref('daily_case_updates').child(id).remove();
            }
        } catch (e) {
            console.warn('Sync delete notice:', e);
        }
        toast('Update entry deleted.', 'info');
        renderDailyCaseUpdates();
    };

