    window.clearAllLeadsAndDump = function(confirmAction = true) {
        if (confirmAction && typeof confirm === 'function' && !confirm("Are you sure you want to clear all leads, enquiries, and dump store items to restart workflow testing from scratch?")) {
            return;
        }
        leads = [];
        enquiries = [];
        if (leadsRef && typeof leadsRef.set === 'function') {
            leadsRef.set([]);
        }
        if (enquiriesRef && typeof enquiriesRef.set === 'function') {
            enquiriesRef.set([]);
        }
        if (typeof saveLocalTableAll === 'function') {
            saveLocalTableAll('leads', []);
            saveLocalTableAll('enquiries', []);
        }
        try {
            localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify({
                leads: [],
                enquiries: [],
                reminders: reminders || [],
                tasks: tasks || [],
                escalations: escalations || [],
                loanTypes: loanTypes || [],
                dailyCaseUpdates: window.dailyCaseUpdates || []
            }));
        } catch(e) {
            console.warn('Failed clearing local state', e);
        }
        if (typeof refreshCurrentPage === 'function') refreshCurrentPage();
        if (confirmAction && typeof showToast === 'function') showToast("All leads and dump store items cleared successfully!", "success");
    };

    window.purgeAllDummyEnquiries = function(notify = false) {
        let removedCount = 0;
        enquiries = (enquiries || []).filter(e => {
            const isDum = isDummyEnquiry(e);
            if (isDum) removedCount++;
            return !isDum;
        });

        try {
            const stored = localStorage.getItem(LOCAL_STORAGE_KEY);
            if (stored) {
                const parsed = JSON.parse(stored);
                if (parsed && Array.isArray(parsed.enquiries)) {
                    const before = parsed.enquiries.length;
                    parsed.enquiries = parsed.enquiries.filter(e => !isDummyEnquiry(e));
                    if (parsed.enquiries.length !== before) {
                        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(parsed));
                    }
                }
            }
        } catch(e) {
            console.warn('Error purging local dummy enquiries:', e);
        }

        if (typeof saveLocalTableAll === 'function') {
            saveLocalTableAll('enquiries', enquiries);
        }

        DUMMY_ENQUIRY_IDS.forEach(id => {
            if (typeof enquiriesRef !== 'undefined' && enquiriesRef && typeof enquiriesRef.child === 'function') {
                try { enquiriesRef.child(id).remove(); } catch(e) {}
            }
        });

        if (currentPage === 'enquiries' && typeof renderEnquiries === 'function') {
            renderEnquiries();
        } else if (currentPage === 'dump-store' && typeof renderDumpStore === 'function') {
            renderDumpStore();
        }
        if (typeof updateBadges === 'function') updateBadges();

        if (notify && typeof toast === 'function') {
            toast(removedCount > 0 ? `Removed ${removedCount} dummy enquiries` : 'All dummy enquiries have been cleared', 'info');
        }
    };

    // Automatically purge dummy enquiries on startup across all employee sessions
    window.purgeAllDummyEnquiries(false);

